INSERT INTO "tutorials" ("id", "slug", "title", "difficulty", "safety_level", "minutes", "reviewer", "related_product_skus", "excerpt", "category", "location", "has_video", "cover_photo_id", "cover_gradient", "content_json", "published_at", "views") VALUES
	(2, 'cambiar-interruptor-desgastado', 'Cambiar un interruptor desgastado sin volverte loco', 'media', 'basic', 25, 'Alfonso Torres', '["14787801","14788004"]', 'Chisporroteo al encender, tecla que no vuelve, calor en el plástico: los síntomas de un mecanismo cansado. Lo cambias en 25 minutos con un destornillador aislado.', 'mecanismos', 'interior', 0, '1621905251189-08b45d6a269e', 'linear-gradient(135deg, #1C1F26, #0B0D12)', '{"hero_eyebrow":"Mecanismos","hero_subtitle":"Si al encender oyes un chisporroteo, la tecla no vuelve a su sitio o notas calor, el mecanismo está para cambio. En 20-30 minutos lo haces tú con un destornillador aislado.","intro_paragraphs":["Un interruptor es un mecanismo con vida útil. Dentro de la tecla que tocas hay dos contactos metálicos que chocan entre sí cada vez que enciendes la luz. Con los años (y los miles de pulsaciones), esos contactos se oxidan o se deforman.","Si reconoces alguno de los síntomas, no esperes: cámbialo. Es de los trabajos más fáciles de Hazlo Tú Mismo, siempre que respetes la secuencia de seguridad."],"why_section":{"title":"Un interruptor es un mecanismo con vida útil.","body":"Dentro de la tecla hay dos contactos metálicos que se tocan y separan cada pulsación. Con el desgaste:","bullets":["<strong>Chisporroteo audible:</strong> el contacto ya no es limpio y salta un pequeño arco eléctrico.","<strong>Tecla que no vuelve o se queda \"blanda\":</strong> el muelle interior está cansado.","<strong>Calor al tocar la tecla:</strong> señal clara de que hay resistencia donde no debería."]},"safety_steps":[{"title":"Desconecta la corriente","body":"En el cuadro general, baja el magnetotérmico de ese circuito. Si no identificas cuál es, baja el diferencial general."},{"title":"Verifica con polímetro","body":"Modo tensión AC. Mide entre fase y neutro del interruptor: debe marcar 0V. No confíes en el automático, confirma."},{"title":"Quítate anillos y pulseras metálicas","body":"Y trabaja sobre suelo seco con calzado aislante."},{"title":"Usa destornillador aislado 1000V","body":"Aunque ya hayas cortado la corriente. Es el mínimo exigible."},{"title":"Haz una foto antes de desconectar cables","body":"Te va a servir cuando tengas dudas sobre dónde iba cada uno."}],"when_not":["Al abrir la caja de registro ves <strong>cables quemados o ennegrecidos</strong>.","La caja tiene <strong>más de tres circuitos juntos</strong> y no los diferencias.","El interruptor está <strong>en zona húmeda sin IP adecuada</strong> (baño junto a ducha, exterior sin tapa).","No consigues <strong>cortar la tensión</strong> con ningún automático."],"steps":[{"title":"Retira la tecla y el marco","body":"Haz palanca con el destornillador plano en las pestañas laterales de la tecla (hay un hueco dedicado). Luego retira el marco. Verás el mecanismo atornillado a la caja universal."},{"title":"Afloja los tornillos que sujetan el mecanismo","body":"Son dos tornillos laterales (sistema de \"garras\") o uno central según modelo. Sácalo un par de vueltas y tira del mecanismo hacia ti con suavidad. Aún está conectado por los cables.","tip":"Si el mecanismo lleva años, el plástico de las garras puede estar frágil. Afloja con cuidado, no fuerces."},{"title":"Haz una foto antes de desconectar los cables","body":"En serio, hazla. Un interruptor simple lleva dos cables (fase de entrada + fase de salida a la lámpara). Un conmutador lleva tres. Saca foto, etiqueta mentalmente o pon cinta con rotulador."},{"title":"Suelta los cables del viejo y conéctalos al nuevo","body":"Afloja el tornillo de cada borne, saca el cable. Revisa las puntas: si están dobladas, ennegrecidas o muy oxidadas, córtalas limpias y pela 8 mm nuevos. Inserta en el mismo borne equivalente del mecanismo nuevo y aprieta bien.","warn":"El cable debe entrar hasta que el aislante toque el borde del borne. Nunca dejes cobre desnudo expuesto."},{"title":"Encaja el mecanismo en la caja y aprieta las garras","body":"Alinea el mecanismo horizontalmente con un nivel (si tienes) o a ojo. Aprieta los tornillos de las garras alternando lados para que no quede torcido."},{"title":"Coloca el marco y la tecla, da corriente y prueba","body":"Encaja primero el marco (clic suave), después la tecla (otro clic). Ve al cuadro y sube el magnetotérmico. Prueba encender y apagar. Si la luz responde sin ruido, has terminado."}],"verification_checks":["La tecla vuelve sola al soltarla, con un clic claro.","La luz enciende y apaga sin chispas ni ruido.","El marco está bien sujeto, sin balanceo.","Ninguna parte del mecanismo se calienta tras 10 minutos encendido."],"problems":[{"summary":"Subí el automático y salta al instante","body":"Lo más probable es que hayas conectado los cables haciendo puente o que el cable de fase esté tocando una parte metálica. Vuelve a cortar corriente, revisa con polímetro, y comprueba que cada cable va a su borne correspondiente sin tocar el otro."},{"summary":"La tecla enciende al revés (apagado = arriba)","body":"Es sólo una cuestión de orientación del mecanismo. Córtalo todo otra vez, saca el mecanismo y gíralo 180°. Vuelve a atornillar."},{"summary":"La luz sigue parpadeando con el mecanismo nuevo","body":"El problema no estaba en el interruptor sino en la bombilla o en el portalámparas. Prueba con una bombilla distinta. Si persiste, revisa el portalámparas — es posible que un hilo esté pillado contra la chapa del plafón haciendo masa."}]}', '2026-05-10', 0),
	(4, 'voltios-vatios-amperios-en-5-min', 'Voltios, vatios y amperios en 5 minutos', 'basica', 'basic', 8, 'Equipo GarperLux', '[]', 'La trinidad eléctrica explicada con la analogía del agua: voltios es la presión, amperios el caudal, vatios la energía total que llega al grifo. En 8 minutos los entiendes para siempre.', 'fundamentos', 'interior', 0, '1500648767791-00dcc994a43e', 'linear-gradient(135deg, #E4DCCA, #B8753A)', '{"hero_eyebrow":"Fundamentos","hero_subtitle":"Antes de tocar nada eléctrico, hay que entender los tres conceptos básicos que aparecen en TODOS los aparatos: voltios (V), amperios (A) y vatios (W). En 8 minutos los tienes claros sin necesidad de fórmulas matemáticas.","intro_paragraphs":["Cualquier aparato eléctrico que compres lleva etiquetada su información: \"230V 10A 2300W\". Si entiendes qué significa, puedes saber si tu instalación lo soporta, si un cable es apropiado, o si un fusible se va a quemar.","La forma más intuitiva de entenderlo es comparar la electricidad con el agua. Spoiler: V es la presión, A es el caudal, W es el total."],"why_section":{"title":"La analogía del agua (válida al 100%).","body":"Imagina un grifo conectado a una tubería:","bullets":["<strong>Voltios (V) = presión:</strong> a más presión, más fuerza tiene el agua. En España: 230V de red doméstica.","<strong>Amperios (A) = caudal:</strong> cuánta agua sale por segundo. Cuanta más necesita un aparato, más cable y más protección necesita.","<strong>Vatios (W) = potencia total:</strong> presión × caudal. Es el agua total que sale del grifo en cada segundo. La factura te la pagan en kWh — kilovatios-hora.","<strong>La fórmula:</strong> W = V × A. Si conoces dos, calculas el tercero."]},"safety_steps":[{"title":"Este tutorial es informativo — no requiere precauciones físicas","body":"Léelo, asimílalo, y aplica el conocimiento en futuros tutoriales."},{"title":"Nunca calcules con valores aproximados en instalaciones reales","body":"Si dudas si un cable soporta los amperios, consulta tabla específica o llama a técnico."},{"title":"Las potencias se suman cuando los aparatos están en paralelo","body":"Un secador (2000W) + una plancha (1500W) en el mismo enchufe = 3500W. Tu circuito de 16A aguanta 3680W máximo."},{"title":"Convierte siempre antes de calcular","body":"kW → W (multiplica por 1000). kWh → Wh (multiplica por 1000). mA → A (divide por 1000)."},{"title":"Si la potencia en factura es la \"contratada\"","body":"No te dejes confundir: tu casa tiene una potencia CONTRATADA (Ej. 4,6 kW) que limita el ICP. Si superas ese tope, salta toda la casa."}],"when_not":["Estás haciendo cálculos para una <strong>instalación nueva</strong> (no reparación) — requiere certificación profesional.","Estás dimensionando <strong>protecciones de cuadro</strong> — esto se hace con tabla normativa, no con cálculos a ojo.","Vas a <strong>conectar varios aparatos potentes</strong> sumando potencias y no estás seguro — mejor pregunta antes que quemar nada.","Trabajas en <strong>media tensión (>1000V)</strong> — esto ya no aplica a tutoriales DIY de ninguna manera."],"steps":[{"title":"Memoriza la fórmula: W = V × A","body":"Es la única que necesitas. Vatios igual a voltios por amperios. Reordena según lo que conozcas: A = W ÷ V, V = W ÷ A."},{"title":"Practica con tu secador","body":"Mira la etiqueta: \"230V 2000W\". Calcula amperios: A = 2000 ÷ 230 ≈ 8,7A. Necesita un circuito de mínimo 10A."},{"title":"Practica con tu lavadora","body":"\"230V 10A\" (a veces no ponen vatios). Calcula vatios: W = 230 × 10 = 2300W. Tu lavadora consume al máximo 2,3 kW (durante el calentamiento del agua)."},{"title":"Calcula tu potencia contratada en amperios","body":"Si tu contrato es 4,6 kW: A = 4600 ÷ 230 = 20A. Si todas las cargas suman más de 20A simultáneas, el ICP salta."},{"title":"Mira tu factura: kWh","body":"Un kWh significa: durante 1 hora has consumido 1000 vatios (=1 kW). Un secador de 2000W usado durante 30 minutos = 1 kWh. La factura te cobra eso a precio del día (0,10 - 0,25 €/kWh según horario y comercializadora)."},{"title":"Aplícalo a la elección de un cable","body":"Un cable 1,5 mm² aguanta hasta 16A (3680W a 230V). Un cable 2,5 mm² aguanta 25A (5750W). Tu cocina de inducción de 7400W necesita 2,5 mm² mínimo."}],"verification_checks":["Entiendes que voltios es presión, amperios caudal, vatios potencia total.","Aplicas la fórmula W = V × A sin hesitar.","Puedes mirar la etiqueta de un electrodoméstico y deducir qué cable y qué protección necesita.","Sabes interpretar la factura de la luz en kWh consumidos."],"problems":[{"summary":"Tengo el dato en kW y mi calculadora me da números raros","body":"Has confundido kW (kilovatios) con W (vatios). 1 kW = 1000 W. Si tu lavadora dice 2,3 kW, en la fórmula W = V × A sustituye W por 2300, no por 2,3."},{"summary":"La factura me cobra MUCHOS más kWh de los que calculo manualmente","body":"Hay consumos invisibles: standby de electrónica (5-15W cada aparato), bombillas LED siempre encendidas, frigorífico (1-2 kWh/día), bomba de calefacción si la tienes. Suma todo durante un mes y el cálculo cuadra."},{"summary":"Mi circuito de 10A pone que está \"al límite\" con un solo aparato","body":"El aparato puede tener picos de arranque de 2-3 veces su consumo nominal. Una nevera de 200W al arrancar el compresor puede tirar 800-1000W durante 1-2 segundos. Por eso los magnetotérmicos tienen \"curva C\" (toleran picos breves)."}]}', '2026-05-10', 0),
	(114, 'cambiar-enchufe-schuko-suelto', 'Cambiar un enchufe Schuko que se ha quedado suelto', 'basica', 'basic', 20, 'Alfonso Torres', '["14787843","14788004"]', 'Al enchufar la lavadora se sale solo, baila en la pared o calienta el plástico. Cambiar la base Schuko es 20 minutos de trabajo limpio.', 'mecanismos', 'interior', 0, '1632833239869-a37e3a5806d2', 'linear-gradient(135deg, #1C1F26, #0B0D12)', '{"hero_eyebrow":"Mecanismos","hero_subtitle":"Cuando una base de enchufe se mueve al meter la clavija o calienta al usar electrodomésticos potentes, es momento de sustituirla. Es de los trabajos más sencillos del manual.","intro_paragraphs":["Una base Schuko (la europea con dos contactos de tierra a los lados) tiene unos muelles internos que aprietan la clavija. Esos muelles, con miles de inserciones, se aflojan. Cuando además circula corriente alta (lavadora, microondas, plancha), los contactos se calientan y el plástico se va degradando.","Cambiarla cuesta menos de 8 euros y se hace en 20 minutos. Si el cable de detrás está sano, es un trabajo perfectamente DIY."],"why_section":{"title":"Un Schuko gastado no es solo molesto, es peligroso.","body":"Si la clavija no hace contacto firme se genera un arco eléctrico, y eso significa:","bullets":["<strong>Calor en la base:</strong> el plástico amarillea o se reblandece.","<strong>Chispazos al enchufar:</strong> el contacto no es franco, salta un arco.","<strong>Marcas negras en los pinchos de la clavija:</strong> síntoma claro de oxidación de contactos.","<strong>Olor a quemado leve:</strong> aviso de que la cosa puede ir a más."]},"safety_steps":[{"title":"Identifica el circuito y baja el magnetotérmico","body":"Generalmente las bases de enchufes están en un circuito distinto al de la luz. Mira la etiqueta del cuadro o, si dudas, baja el diferencial general."},{"title":"Verifica con polímetro entre fase y neutro","body":"Modo tensión AC, 250V. Si marca 0V tienes vía libre. Si marca tensión, no has cortado el circuito correcto: vuelve al cuadro."},{"title":"Trabaja con calzado aislante y manos secas","body":"Aunque hayas verificado ausencia de tensión, mantén las costumbres de seguridad."},{"title":"Destornillador aislado 1000V exclusivamente","body":"Cualquier destornillador normal es un riesgo innecesario."},{"title":"Foto del cableado antes de tocar","body":"Un Schuko lleva tres cables: fase (marrón/negro), neutro (azul) y tierra (verde-amarillo). La tierra siempre va al borne central marcado con un símbolo de toma a tierra."}],"when_not":["Hay <strong>quemaduras visibles en los cables</strong> al sacar el mecanismo: posible cortocircuito previo no resuelto.","La caja universal está rota o la fijación a la pared no aguanta: requiere obra menor.","El enchufe está en <strong>cocina cerca del fregadero o en baño</strong> y la caja no tiene grado de protección IP44 o superior.","No identificas qué cable es la tierra y los colores son no estándar (instalaciones muy antiguas)."],"steps":[{"title":"Quita el marco y la base vieja","body":"Haz palanca con destornillador plano en una de las muescas laterales. El marco salta. Verás dos tornillos sujetando la base a la caja universal."},{"title":"Afloja los tornillos de las garras","body":"Da 3-4 vueltas a cada tornillo (no los saques del todo) y tira del mecanismo hacia ti. Saldrá unos centímetros mostrando los cables conectados por detrás."},{"title":"Identifica los tres cables y haz foto","body":"Marrón/negro = fase. Azul = neutro. Verde-amarillo = tierra. La tierra entra por el borne central; fase y neutro a los dos laterales (su orden no importa para enchufes monofásicos, pero respeta lo que ves)."},{"title":"Desconecta los cables del viejo","body":"Afloja cada tornillo de borne, saca el cable. Si la punta está negra u oxidada, pélala 1 cm más adelante para tener cobre limpio.","warn":"Si encuentras los cables empalmados con clemas sueltas o cinta aislante deshecha, para y llama a un técnico — la instalación tiene problemas previos."},{"title":"Conecta los cables a la base nueva","body":"Tierra al borne central (símbolo ⏚). Fase y neutro a los laterales. Aprieta cada tornillo firme — debe agarrar el cobre, no el aislante. Tira suavemente de cada cable: no debe moverse."},{"title":"Mete el mecanismo y aprieta garras","body":"Encaja la base en la caja con los cables doblados detrás (sin pillarlos). Aprieta las dos garras alternando lados para que quede recto. Coloca marco y tapa."}],"verification_checks":["La clavija de un cargador entra firme, no se queda balanceando ni se sale sola.","Al enchufar un electrodoméstico que consume (secador, plancha) no hay chispazo ni ruido.","El mecanismo no calienta tras 10 minutos con carga.","La tapa queda recta y firme contra la pared."],"problems":[{"summary":"Al dar corriente salta el diferencial","body":"Es muy probable que la tierra esté tocando la fase. Vuelve a cortar, saca el mecanismo y revisa: el cable verde-amarillo solo va al borne central marcado con tierra, nunca debe quedar tocando los otros bornes ni la chapa metálica de la caja."},{"summary":"El enchufe funciona pero la clavija sigue floja","body":"Has comprado una base de calidad baja con muelles débiles, o la clavija que pruebas está deformada. Cambia a una base de marca (Simon 27, Niessen Zenit) y prueba con una clavija distinta para descartar."},{"summary":"La base no llega a fondo y queda saliente de la pared","body":"La caja universal está fuera de plano. Saca la base, mira si la caja gira o si está mal anclada. Puedes apretar la garra más fuerte, pero si el problema persiste hay que recolocar la caja con yeso."}]}', '2026-05-10', 0),
	(115, 'instalar-doble-interruptor-pasillo', 'Instalar un doble interruptor en el pasillo', 'media', 'basic', 30, 'Alfonso Torres', '["14787815","14788004"]', 'Mismo punto de pared, dos circuitos: encender el pasillo y el armario por separado. Cambias un mecanismo simple por uno doble en media hora.', 'mecanismos', 'interior', 0, '1556909114-f6e7ad7d3136', 'linear-gradient(135deg, #40454F, #1C1F26)', '{"hero_eyebrow":"Mecanismos","hero_subtitle":"Un doble interruptor te permite controlar dos cargas distintas (luz del pasillo y luz del armario, por ejemplo) desde el mismo mecanismo. Si la caja universal tiene los cables disponibles, lo instalas en 30 minutos.","intro_paragraphs":["Un doble interruptor ocupa el mismo hueco que un interruptor simple, pero tiene dos teclas y cuatro bornes (en vez de dos). Sirve para controlar dos cargas independientes desde el mismo punto.","Para que funcione, la caja universal debe tener al menos tres cables: una fase común (entrada) y dos retornos (uno por cada carga). Si los cables ya están tirados, esto es media hora de trabajo limpio."],"why_section":{"title":"El uso típico del doble interruptor.","body":"Los casos más habituales donde el doble mecanismo gana:","bullets":["<strong>Pasillo + armario:</strong> dos luces cerca pero independientes.","<strong>Luz principal + tira LED:</strong> ambiente vs lectura en un dormitorio.","<strong>Lámpara de techo + apliques de mesilla:</strong> control conjunto desde la puerta.","<strong>Salón con lámparas en lados opuestos:</strong> evita andar de un punto a otro."]},"safety_steps":[{"title":"Identifica AMBOS circuitos en el cuadro","body":"Si las dos cargas pertenecen a circuitos distintos, hay que cortar los dos. Generalmente irán al mismo magnetotérmico de iluminación, pero confirma."},{"title":"Verifica con polímetro las dos fases","body":"Mide entre cada par de cables sospechosos: deben marcar 0V todos. Algunos circuitos comparten fase pero no es seguro asumirlo."},{"title":"Trabajo en seco, sin metales en manos","body":"Lo de siempre. Suelo seco, sin anillos, sin pulseras."},{"title":"Destornillador aislado 1000V","body":"Sin excepción."},{"title":"Foto del cableado actual antes de tocar","body":"Con un doble pueden aparecer combinaciones raras heredadas de obra. La foto te ayuda si tienes que volver al estado inicial."}],"when_not":["Solo hay <strong>dos cables</strong> en la caja universal — no puedes hacer un doble sin cablear una nueva línea.","La caja tiene <strong>cables sin identificar</strong> y no consigues distinguir cuál es fase común y cuál retorno.","Una de las cargas que quieres controlar <strong>no está cableada hasta esa caja</strong> (hay que tirar manguera).","Detectas que el circuito comparte fase con un mecanismo de otra habitación — eso es una redistribución, no un cambio."],"steps":[{"title":"Quita la tecla, el marco y el mecanismo simple","body":"Como en cualquier cambio: palanca con destornillador plano en las muescas, retira marco y afloja garras."},{"title":"Identifica los cables","body":"Saca el mecanismo unos centímetros y mira la caja: debes ver 3 cables (1 fase + 2 retornos) o 4 cables (1 fase + 2 retornos + 1 neutro si el cableado es más moderno). El neutro azul no se usa en un interruptor convencional — déjalo aislado con clema."},{"title":"Marca cada cable con cinta de color","body":"Pon una banda de cinta de un color al cable de fase (entrada), de otro color al retorno A y de otro color al retorno B. Te ahorra muchas dudas al conectar.","tip":"Si solo tienes cinta blanca, escribe con bolígrafo ''F'', ''A'' y ''B'' en la cinta para identificarlos."},{"title":"Conecta al doble interruptor","body":"El doble lleva un borne común marcado ''L'' o con un símbolo de entrada — ahí va la fase. Los otros dos bornes (uno por cada tecla) reciben los retornos A y B.","warn":"No metas dos cables en el mismo borne salvo que el fabricante lo permita expresamente (algunos modelos Simon 27 sí lo permiten con 2 cables de 1,5 mm² máximo)."},{"title":"Tira de cada cable para confirmar el apriete","body":"Cada cable debe quedar firme. Si uno se mueve, vuelve a apretar el tornillo. Cobre asomando = recorta y vuelve a meter."},{"title":"Coloca mecanismo, marco con dos teclas y prueba","body":"Encaja el mecanismo en la caja universal y aprieta garras. El marco de doble lleva una tapa con DOS teclas. Encájalas, da corriente y prueba cada tecla por separado."}],"verification_checks":["Cada tecla controla SU carga, no la del compañero.","Ninguna tecla afecta a la otra (si una está encendida, la otra responde independiente).","Las dos teclas hacen clic claro y vuelven solas.","El mecanismo no calienta con ambas cargas encendidas durante 10 minutos."],"problems":[{"summary":"Al dar corriente se encienden ambas luces a la vez","body":"Has cruzado los retornos con la fase común. Probablemente metiste los dos retornos en el borne común. Corta corriente, revisa la conexión: el borne marcado ''L'' o ''↵'' solo lleva la fase de entrada (UNA), los otros dos bornes (uno por tecla) llevan retornos."},{"summary":"Una tecla funciona y la otra no","body":"Ese retorno no llega bien al borne o no llega bien a la carga. Verifica con polímetro continuidad entre el borne del mecanismo y el portalámparas correspondiente. Si la continuidad existe, revisa que el cable está bien apretado."},{"summary":"Las teclas hacen al revés (la izquierda enciende lo de la derecha y viceversa)","body":"Solo has intercambiado los dos retornos. Corta corriente, intercambia los dos cables de retorno entre sus bornes y listo."}]}', '2026-05-10', 0),
	(116, 'montar-conmutador-dos-puntos', 'Montar un conmutador: encender desde dos puntos', 'media', 'basic', 35, 'Alfonso Torres', '["82952489","17915884","14788004"]', 'Subir la luz al dormitorio y poder apagarla desde la cama. Un par de conmutadores y manguera 3x1,5 — y sin más interruptores de los necesarios.', 'mecanismos', 'interior', 0, '1565192259022-fdeed9c7b46e', 'linear-gradient(135deg, #1C1F26, #0B0D12)', '{"hero_eyebrow":"Mecanismos","hero_subtitle":"Un conmutador (también llamado interruptor de tres vías) te deja encender y apagar la misma luz desde dos puntos. Es lo que se usa en pasillos, escaleras, dormitorios. Necesitas dos conmutadores y manguera de 3 hilos entre ellos.","intro_paragraphs":["Un conmutador tiene tres bornes en lugar de dos. Cada conmutador conecta la entrada con UNO de los dos retornos. Si dos conmutadores se cablean correctamente entre sí, cambiar el estado de cualquiera de ellos cambia el estado de la lámpara.","Si los cables aún no están tirados entre los dos puntos, vas a necesitar pasar manguera 3x1,5 mm² por moldura, falso techo o regata. Eso convierte este tutorial de 35 min en un proyecto de varias horas — valóralo antes de empezar."],"why_section":{"title":"Dónde tiene sentido un conmutador.","body":"Los casos clásicos:","bullets":["<strong>Dormitorio:</strong> encender desde la puerta y apagar desde la cama.","<strong>Pasillo largo:</strong> luz desde cada extremo para no andar a oscuras.","<strong>Escaleras:</strong> uno arriba, uno abajo (obligatorio por seguridad).","<strong>Salón con dos entradas:</strong> mando desde ambas puertas."]},"safety_steps":[{"title":"Corta el circuito completo de iluminación","body":"Si tienes que pasar manguera nueva entre dos puntos, conviene cortar el diferencial general — vas a manipular cables en zonas que pueden estar próximas a otros circuitos."},{"title":"Verifica con polímetro en ambos extremos","body":"Mide en la caja de cada conmutador: 0V entre cualquier par de cables."},{"title":"Quítate metales, suelo seco","body":"Lo de siempre. Si vas a subir a escalera, alguien sujeta abajo."},{"title":"Destornillador aislado 1000V","body":"Sin excepción."},{"title":"Marca CADA cable que toques con cinta de color","body":"Con conmutadores es facilísimo cruzarlos. Marca: ''F'' fase de entrada, ''L'' al portalámparas, ''A'' y ''B'' los dos conmutados."}],"when_not":["La distancia entre los dos puntos exige <strong>obra de albañilería</strong> (regata) que no estás preparado para hacer.","Hay que <strong>cruzar circuitos protegidos</strong> distintos (no debe juntarse iluminación con tomas de corriente en la misma manguera).","El conmutador irá en zona húmeda o exterior y no tienes los grados IP adecuados.","El cableado existente es de <strong>aluminio</strong> (instalaciones de antes de 1970) — requiere técnico autorizado."],"steps":[{"title":"Planifica el recorrido de la manguera","body":"Decide por dónde va la manguera 3x1,5: por moldura externa (rápido pero feo), por falso techo (si lo tienes) o por regata (obra). Mide la longitud y compra 30 cm más de margen."},{"title":"Pasa la manguera entre los dos puntos","body":"Si vas por moldura, usa guía pasacables o, si la moldura está en paredes con curvas, tira directamente. Si vas por falso techo, fija cada metro con bridas a estructura.","tip":"No tenses la manguera al pasarla; debe quedar holgada para no sufrir con dilataciones."},{"title":"Pela los extremos y prepara las puntas","body":"En cada caja, pela 12 cm del recubrimiento exterior de la manguera. Pela 8 mm de cada hilo. Tendrás 3 hilos: fase del par + dos hilos para conmutación. El verde-amarillo de tierra NO se usa en mecanismo conmutador (déjalo aislado dentro de la caja)."},{"title":"Conecta el conmutador A (lado de entrada de fase)","body":"Borne común (marcado ''L'' o con flecha de entrada): cable de fase del circuito. Bornes 1 y 2: los dos hilos de la manguera que va al conmutador B. Aprieta bien y comprueba con tirón.","warn":"Si tu conmutador no tiene los bornes marcados, mira la ficha técnica del fabricante. En Simon 27 (referencia 27201-31), el borne común es el del centro."},{"title":"Conecta el conmutador B (lado del portalámparas)","body":"Borne común: cable que va al portalámparas. Bornes 1 y 2: los dos hilos que llegan del conmutador A (los mismos dos hilos de la manguera). Importante: que los hilos 1 y 2 del conmutador A vayan a los bornes 1 y 2 del B respetando el orden."},{"title":"Coloca marcos, da corriente y prueba","body":"Ambos mecanismos en sus cajas, marcos colocados, teclas encajadas. Sube el magnetotérmico. Acciona el conmutador A: la luz debe encenderse. Acciona el B: debe apagarse. Y viceversa."}],"verification_checks":["Cualquiera de los dos conmutadores cambia el estado de la luz.","Si la luz está encendida y accionas uno, se apaga; si está apagada y accionas el otro, se enciende.","Ambas teclas tienen tacto firme y vuelven a su posición.","Sin chisporroteos al accionar; ningún mecanismo calienta tras 10 minutos."],"problems":[{"summary":"Solo uno de los dos conmutadores enciende la luz, el otro no hace nada","body":"Has cruzado los hilos 1-2 entre los dos conmutadores: el borne 1 del A va al borne 1 del B y el borne 2 al 2 (no se cruzan). Verifica con polímetro la continuidad de cada par de hilos por separado. Si la continuidad es correcta, revisa el borne común del que no funciona — quizás el cable se ha soltado."},{"summary":"La luz se queda encendida fijo, no responde a ningún conmutador","body":"Has unido los dos hilos conmutados directamente o el borne común está cortocircuitado. Vuelve a desmontar y revisa el esquema: el borne común NUNCA debe ir conectado a los otros dos."},{"summary":"Al dar corriente salta el magnetotérmico","body":"Posible cortocircuito en la manguera (un hilo pelado tocando otro dentro de la canalización). Saca los conmutadores y verifica continuidad entre los hilos de la manguera sin conectar: cada hilo debe estar aislado del resto. Si encuentras continuidad indebida, hay daño y hay que cambiar la manguera."}]}', '2026-05-10', 0),
	(117, 'cambiar-marco-simon-75-grafito', 'Renovar marcos antiguos por Simon S270', 'basica', 'basic', 10, 'Alfonso Torres', '["85164262","85164288"]', 'Cambio cosmético sin tocar ni un cable: pasa de gama Simon 27 blanca a gama Simon 75 grafito en diez minutos. Aire profesional en cualquier pared.', 'mecanismos', 'interior', 0, '1556909114-f6e7ad7d3136', 'linear-gradient(135deg, #40454F, #1C1F26)', '{"hero_eyebrow":"Mecanismos","hero_subtitle":"A veces la instalación está bien pero los mecanismos viejos cantan. Si la base interna (caja universal de 60 mm) está en buen estado, puedes mantener todo el cableado y cambiar solo el aspecto: mecanismo + marco a una gama moderna como Simon 75 en acabado grafito.","intro_paragraphs":["Los mecanismos eléctricos modernos (Simon 27, 75, 82, 100) son compatibles entre sí en cuanto a fijación a caja universal. Eso significa que puedes cambiar la apariencia de toda la casa sin tocar la instalación.","Este trabajo es ideal para reformas de bajo coste: 10 minutos por punto, sin polvo, sin obras y con un cambio estético importante."],"why_section":{"title":"Por qué Simon 75 funciona para reformas.","body":"La gama 75 es la elegida cuando se busca:","bullets":["<strong>Acabado mate moderno:</strong> grafito o blanco antiguo (no brillo plástico).","<strong>Compatibilidad universal:</strong> entra en cualquier caja de 60 mm.","<strong>Marcos coordinables:</strong> 1, 2, 3 o 4 elementos en la misma caja embellecedora.","<strong>Catálogo amplio:</strong> hay versiones para todo: TV, USB, regulador, conmutador, doble."]},"safety_steps":[{"title":"Corta el circuito del punto que vas a cambiar","body":"Magnetotérmico de iluminación o de enchufes según corresponda. Si haces varios puntos, mejor el diferencial general."},{"title":"Verifica con polímetro","body":"0V entre los cables del mecanismo."},{"title":"Sin metales en manos, suelo seco","body":"Lo de siempre — aunque sea trabajo aparente, sigues moviendo cables."},{"title":"Destornillador aislado 1000V","body":"Sin excepción."},{"title":"Foto del cableado antes de soltar","body":"Aunque cambias por equivalente, una foto te ahorra dudas."}],"when_not":["El mecanismo viejo está <strong>quemado o con plástico derretido</strong> — antes hay que entender qué pasó.","La <strong>caja universal está rota o gira</strong> al apretar tornillos — requiere recolocación con yeso.","Los cables se han <strong>endurecido y crujen</strong> al doblarlos — instalación muy antigua, plantéate cableado nuevo.","Tienes <strong>mezcla de gamas</strong> en una misma caja y no recuerdas qué marco va con qué — abre primero, mira y decide."],"steps":[{"title":"Quita el marco viejo","body":"Palanca con destornillador plano en la muesca del marco antiguo. Algunos modelos viejos no tienen muesca: apalancas directamente desde un lateral con cuidado de no rayar la pared."},{"title":"Desmonta el mecanismo viejo","body":"Afloja las dos garras (3-4 vueltas), tira hacia ti con suavidad. El mecanismo saldrá unos centímetros mostrando los cables."},{"title":"Transfiere los cables al nuevo mecanismo Simon 75","body":"Borne a borne: lo que estaba en el borne L del viejo va al borne L del nuevo. Lo que estaba en el otro borne va al equivalente. Aprieta bien y verifica con tirón cada cable.","tip":"Si la punta de cobre está oscura tras años de servicio, recorta 1 cm y pela de nuevo. Es 30 segundos extra que aseguran contacto limpio."},{"title":"Encaja el nuevo en la caja universal","body":"Mete el mecanismo Simon 75 con los cables doblados detrás. Aprieta ambas garras alternando lados para que quede recto."},{"title":"Coloca el marco grafito","body":"Los marcos Simon 75 entran a clic — sin tornillos visibles. Alinea con el mecanismo y presiona suavemente hasta que escuches el clic en ambos lados."},{"title":"Da corriente y verifica","body":"Sube el magnetotérmico. Prueba que el mecanismo funciona igual que antes."}],"verification_checks":["El marco grafito está bien encajado, sin hueco entre marco y pared.","El mecanismo funciona idéntico al viejo (mismo encendido/apagado).","Sin chispas, sin ruido, sin calor.","Si has cambiado varios puntos, todos lucen del mismo acabado y orientación."],"problems":[{"summary":"El marco no encaja: queda separado de la pared","body":"La caja universal está fuera de plano. Saca el marco, sácalo todo, y observa la caja: si gira o no apoya firme contra la pared, hay que ajustarla con yeso o cemento blanco. Trabajo de 10 minutos extra."},{"summary":"El mecanismo no enciende tras el cambio","body":"Has cambiado un cable de borne. Vuelve a comparar con la foto que tomaste antes de tocar. Si no tomaste foto, el sistema es: borne común (marcado con flecha o L) recibe la entrada (fase); el otro borne va al portalámparas."},{"summary":"Faltan elementos en marcos múltiples (cubiertas de 2-3-4)","body":"Si has comprado marcos grandes pero solo cambias un mecanismo en esa caja, los huecos sobrantes se cierran con embellecedores ciegos (referencia 75001-30 en gama 75). Pídelos junto al pedido del kit."}]}', '2026-05-10', 0),
	(118, 'entender-temperatura-de-color', 'Entender la temperatura de color: 2700K, 4000K, 6500K', 'basica', 'basic', 8, 'Equipo GarperLux', '["89954095","84844254","83583729"]', 'Por qué se devuelven tantas bombillas: la luz "fría" no es lo que crees. En 8 minutos sabrás qué Kelvin pedir para cada estancia.', 'iluminacion', 'interior', 0, '1585771724684-7b076f6c11ec', 'linear-gradient(135deg, #B8753A, #E8A545)', '{"hero_eyebrow":"Iluminación","hero_subtitle":"El concepto de \"luz cálida\" o \"luz fría\" se mide en Kelvin (K). Y aunque parece contraintuitivo, la luz CÁLIDA tiene menos Kelvin (más amarilla) y la FRÍA tiene más Kelvin (más azulada). Es responsable del 60% de las devoluciones de bombillas LED en el sector.","intro_paragraphs":["La temperatura de color de una luz se mide en grados Kelvin (K) y describe el matiz que percibimos: amarillento, blanco neutro, blanco azulado. NO tiene nada que ver con el calor que emite la bombilla físicamente — es solo sobre el color de la luz.","Elegir el Kelvin equivocado para una habitación es la diferencia entre un salón acogedor y un quirófano frío. No hay solo \"luz buena\" y \"luz mala\": cada estancia tiene su rango óptimo."],"why_section":{"title":"Los tres rangos que tienes que conocer.","body":"Memoriza estas tres referencias y resuelves el 95% de los casos:","bullets":["<strong>2700K - 3000K · Cálida:</strong> salones, dormitorios, restaurantes. Recuerda al filamento de la bombilla incandescente clásica.","<strong>4000K · Neutra:</strong> cocinas, baños, oficinas en casa. Blanco \"papel\". Lo que mejor reproduce los colores reales.","<strong>6500K · Fría:</strong> talleres, garajes, escaparates. Luz azulada que mantiene despierto. Mal para descansar."]},"safety_steps":[{"title":"No requiere precauciones eléctricas","body":"Este tutorial es informativo. Cuando vayas a cambiar la bombilla físicamente, sigue el tutorial de \"Cambiar halógena por LED\"."},{"title":"Antes de comprar, mide la base del casquillo","body":"E27 (rosca grande), E14 (rosca pequeña), GU10 (bipin), G9... cada bombilla tiene su casquillo. Lee la marca en el casquillo viejo."},{"title":"Comprueba en la caja: Kelvin Y lúmenes","body":"El Kelvin define el COLOR. Los lúmenes definen la POTENCIA luminosa. Una LED 9W puede ser 800 lúmenes (clara) o 600 lúmenes (apagada) según marca."},{"title":"Si compras varias para la misma estancia, compra mismo Kelvin y misma marca","body":"Aunque ambas pongan \"4000K\", marcas distintas pueden dar tonos visiblemente distintos."},{"title":"Conserva las cajas durante los primeros días","body":"Los LED bajos de gama suelen tener mortalidad infantil (fallan en los primeros 30 días). Tener la caja te permite reclamar garantía."}],"when_not":["Si solo cambias UNA bombilla en una lámpara con varios casquillos y no recuerdas la temperatura de las demás — mira la caja vieja o cambia todas a la vez.","En zonas <strong>donde necesitas ver detalles finos</strong> (taller de joyería, despacho de costura) la 4000K-5000K es lo correcto, no la cálida.","En dormitorios infantiles, evita la 6500K — afecta a la secreción de melatonina y dificulta el sueño.","No mezcles cálida y fría en la misma estancia salvo que sea una decisión deliberada por zonas."],"steps":[{"title":"Decide la función principal de la estancia","body":"¿Es de descanso (dormitorio, salón) o de actividad (cocina, baño, oficina)? La función marca el rango."},{"title":"Mira la luz natural que recibe durante el día","body":"Habitaciones que dan al norte (luz fría natural) ganan con bombillas cálidas para equilibrar. Habitaciones al sur (luz cálida natural) pueden permitirse algo más neutro."},{"title":"Para salones y dormitorios, escoge 2700K","body":"Es la equivalencia directa a la halógena clásica. Cálida, acogedora, no fatiga la vista por la noche."},{"title":"Para cocinas y baños, escoge 4000K","body":"Reproduce mejor los colores reales (los alimentos, tu cara en el espejo). No marea como la fría pura."},{"title":"Para garajes, talleres y oficinas técnicas, escoge 6500K","body":"Luz blanca pura, máxima atención visual. La idea es mantener el cerebro alerta."},{"title":"Si dudas, opta por 4000K","body":"Es el promedio razonable que funciona en casi cualquier estancia, sin extremos. Si más tarde decides cambiar, las LED de hoy son baratas."}],"verification_checks":["Al encender, la luz se parece a la que imaginabas (no demasiado amarilla ni demasiado azul).","Después de una hora encendida no notas fatiga visual.","Los colores de tu mobiliario se ven similares a como los ves con luz natural.","Si comparas con otra bombilla del mismo Kelvin/marca, son visualmente idénticas."],"problems":[{"summary":"He comprado 4000K y la luz me parece muy fría","body":"Es porque vienes de bombillas incandescentes (2700K aprox). Tu ojo aún espera el tono amarillo. Dale 2-3 días: te acostumbras. Si pasada una semana sigues sin gustarte, devuélvela y prueba 3000K."},{"summary":"Mezclo 2700K y 4000K en la misma lámpara y queda raro","body":"Las mezclas dentro de un mismo plafón siempre se notan. Saca la \"discordante\" y compra una del mismo Kelvin que las demás. El extra de 4 euros vale más que el feo permanente."},{"summary":"Mi LED dice 2700K en la caja pero la luz parece blanca pura","body":"Marcas low-cost a veces falsean el Kelvin. Devuélvela y compra de marca conocida (Philips, Osram, Lexman, Matel). El sobreprecio se nota en calidad y consistencia."}]}', '2026-05-10', 0),
	(119, 'cambiar-halogena-por-led', 'Cambiar una halógena por LED equivalente', 'basica', 'basic', 5, 'Equipo GarperLux', '["89954095","89954100"]', 'Ahorras 85% de electricidad sin notar diferencia visual. Solo necesitas saber qué LED equivale a tu halógena (pista: NO mires los vatios, mira los lúmenes).', 'iluminacion', 'interior', 0, '1585771724684-7b076f6c11ec', 'linear-gradient(135deg, #B8753A, #E8A545)', '{"hero_eyebrow":"Iluminación","hero_subtitle":"Una halógena de 60W se reemplaza por una LED de aproximadamente 9W con los mismos lúmenes. Misma luz, 85% menos consumo, duración 10× superior. Es el upgrade más rentable que puedes hacer en casa.","intro_paragraphs":["Las bombillas halógenas (las del filamento) están en proceso de retirada por la UE y consumen mucho. Una LED moderna te da exactamente la misma luz consumiendo una fracción de la electricidad.","La equivalencia entre halógena y LED no es 1:1 en vatios — los vatios miden consumo, no luz. La unidad de luz son los lúmenes."],"why_section":{"title":"Por qué cambiar todas tus halógenas ya.","body":"El cambio se amortiza solo, y por varios motivos:","bullets":["<strong>Consumo:</strong> 85% menos electricidad (de 60W → 9W).","<strong>Duración:</strong> 25.000h vs 2.000h. Una LED dura 10-15 años en uso normal.","<strong>Calor:</strong> una halógena de 60W llega a 250°C en la superficie. Una LED apenas calienta.","<strong>Encendido instantáneo:</strong> sin tiempo de calentamiento como los antiguos fluorescentes."]},"safety_steps":[{"title":"Apaga el interruptor antes de tocar la bombilla","body":"Aunque la bombilla esté fría, manipular casquillos vivos es riesgo eléctrico innecesario."},{"title":"Si acabas de apagar la halógena, espera 5 minutos","body":"Una halógena recién apagada está extremadamente caliente (puede quemarte). Una LED nunca."},{"title":"Sin necesidad de polímetro ni cuadro","body":"Es un cambio físico, no eléctrico. El apagado del interruptor es suficiente para bombillas en aplique normal."},{"title":"Para lámparas de techo a más de 2,5m de altura, usa escalera estable","body":"Si la escalera baila, alguien sujeta abajo. Las caídas por cambio de bombilla son una de las causas más frecuentes de urgencias en hogar."},{"title":"Bombilla nueva en mano, comprueba que NO está rota","body":"Las LED bajos de gama pueden venir con el difusor agrietado. Una grieta en el difusor no afecta la luz pero puede comprometer la IP."}],"when_not":["La lámpara tiene <strong>regulador (dimmer)</strong> y la LED no es regulable — busca específicamente \"LED regulable\" o \"dimmable\".","El portalámparas está <strong>oxidado o ennegrecido</strong>: cambia el portalámparas también o consulta tutorial específico.","La halógena está en un <strong>portafocos cerrado sin ventilación</strong> que retiene calor — la LED nueva podría sufrir por falta de disipación.","El casquillo es <strong>tipo R7s (lineal halógena)</strong>: hay LED equivalente pero su instalación es algo más delicada."],"steps":[{"title":"Identifica el casquillo de tu halógena","body":"Mira la base de la bombilla vieja. Los más comunes en casa: E27 (rosca grande), E14 (rosca pequeña), GU10 (bipin retorcido), G9 (dos pines rectos)."},{"title":"Mira los vatios o los lúmenes de la halógena","body":"Si viene marcado \"60W\" o \"100W\", busca la equivalencia LED en lúmenes. Equivalencia rápida: <br>40W → 470lm → 5-6W LED<br>60W → 800lm → 8-9W LED<br>100W → 1500lm → 13-15W LED"},{"title":"Decide la temperatura de color que quieres","body":"Mismo Kelvin que tenías o nuevo si decides cambiar el ambiente. Por defecto, 2700K te dará la misma sensación que la halógena.","tip":"Si tienes varias bombillas en la misma estancia y solo cambias una, intenta que todas tengan el mismo Kelvin para que no canten."},{"title":"Saca la halógena vieja","body":"Apaga el interruptor. Si llevaba un rato encendida, espera 5 minutos a que enfríe. Desenrosca (E27/E14), tira recto (G9), gira 1/4 (GU10) según el tipo."},{"title":"Coloca la LED nueva","body":"Mismo gesto al revés. Aprieta sin forzar — los plásticos modernos no necesitan apretar como las viejas de loza."},{"title":"Da corriente y comprueba","body":"Enciende el interruptor. La LED se ilumina al instante (sin parpadeo de calentamiento). Si parpadea repetidamente al encender, revisa el portalámparas — puede tener contacto sucio."}],"verification_checks":["La LED enciende al instante, sin retraso.","El nivel de luz es similar o mayor al que tenías con la halógena.","El color de la luz es el que esperabas (no demasiado amarillo ni demasiado azul).","Al tocar la LED después de 5 minutos encendida, está fría o ligeramente tibia (no caliente)."],"problems":[{"summary":"La LED parpadea ligeramente al encender o cuando hay otra carga","body":"Tu interruptor lleva piloto luminoso interno (esos rojos que se ven en oscuro) o tienes regulador no compatible. El piloto deja pasar microcorriente que la LED detecta. Solución: bombilla LED con \"protección anti-parpadeo\" o quitar el piloto del interruptor."},{"summary":"La LED dura menos de 2 años cuando deberían ser 15","body":"Probable causa: portalámparas con mala ventilación o LED de marca low-cost con disipador pobre. Cambia a marca buena (Philips, Osram, Lexman, Matel) y verifica que el portafocos no esté cerrado herméticamente."},{"summary":"El interruptor zumba ligeramente con la LED instalada","body":"Interferencia entre el regulador del interruptor (si es regulable) y el driver de la LED. Cambia a una LED específicamente etiquetada como compatible con dimmer. Si tu interruptor no es regulador, revisa que no haya tomado un contacto sucio."}]}', '2026-05-10', 0),
	(120, 'instalar-proyector-led-fachada', 'Instalar un plafón LED Ikaros en la fachada', 'avanzada', 'high', 60, 'Alfonso Torres', '["91468802","17915884"]', 'Foco LED 50W IP65 con sensor crepuscular para fachada. 60 minutos de trabajo + algo de mano para la regata, y una entrada bien iluminada y segura.', 'iluminacion', 'exterior', 0, '1558618666-fcd25c85cd64', 'linear-gradient(135deg, #1C1F26, #B8753A)', '{"hero_eyebrow":"Iluminación","hero_subtitle":"Un proyector LED IP65 en la fachada da seguridad y bienvenida. La instalación correcta pasa por elegir altura, anclaje a obra, alimentación protegida y orientación final. Si te organizas, lo dejas listo en 60 minutos efectivos.","intro_paragraphs":["Un proyector exterior de 50W tipo IP65 vale por un punto de luz a la antigua de 200W halógena. Aporta seguridad, decoración y, si lo combinas con sensor crepuscular o detección de movimiento, eficiencia energética.","Lo que más cuesta NO es montar el proyector — es decidir bien dónde, cómo alimentarlo (regata, moldura, manguera vista por exterior) y dar con un anclaje seguro a la fachada. Si vives en piso alquilado, esta tarea probablemente no aplica."],"why_section":{"title":"Cuándo conviene un proyector exterior.","body":"Los casos típicos donde un proyector LED gana frente a un aplique:","bullets":["<strong>Iluminación de fachada o garaje:</strong> mayor distancia de alcance.","<strong>Pasos peatonales hacia la puerta:</strong> claridad sin sombras duras.","<strong>Patios o terrazas grandes:</strong> baña una superficie amplia.","<strong>Combo con detección de movimiento:</strong> efecto disuasorio si tiendes a tener visitas no deseadas."]},"safety_steps":[{"title":"Corta TODO el suministro al exterior","body":"Diferencial general, no solo el de iluminación. En instalaciones antiguas, el exterior suele compartir línea con otras cargas."},{"title":"Verifica ausencia de tensión EN EL PUNTO de instalación","body":"Sube a la altura prevista del foco con polímetro y mide en el cable que vas a usar para alimentar. Si hay 230V, no has cortado el circuito correcto."},{"title":"No trabajes con lluvia, humedad alta ni mojado","body":"Exterior + agua + electricidad = no. Si el día se pone feo, posponer."},{"title":"Escalera estable, alguien sujeta abajo","body":"Caer desde 3m con destornillador en mano es de las cosas peores. No improvises soportes."},{"title":"Destornillador aislado 1000V y guantes dieléctricos si tienes","body":"Para exterior conviene el extra de protección. Los guantes dieléctricos no son caros."}],"when_not":["La <strong>fachada es de panel sandwich o material delicado</strong> que no admite taladros para anclaje en el peso del proyector — requiere subestructura.","El exterior NO tiene <strong>circuito propio con toma de tierra</strong>: tirar uno nuevo es trabajo de instalador autorizado por boletín.","El proyector va a quedar <strong>a menos de 50 cm de una toma de agua</strong> (grifo, manguera de riego) — necesitas IP67 y aislamiento extra.","Vives en <strong>comunidad de vecinos</strong> y la instalación afecta a fachada — necesitas permiso de la junta."],"steps":[{"title":"Decide la ubicación y altura definitiva","body":"Para fachada estándar, 2,8 a 3,5 m del suelo. Apuntando hacia el suelo unos 30-40° para iluminar la zona de paso sin deslumbrar a peatones. Marca con lápiz dónde irá el centro del soporte."},{"title":"Tira la alimentación desde la caja más cercana","body":"Manguera 3x1,5 mm² (fase + neutro + tierra). Si vas por exterior, usa canalización tubo PVC corrugado tipo M16 o M20. Si vas por interior con salida a fachada, perfora con taladro adecuado."},{"title":"Conecta a un interruptor o sensor","body":"Si el proyector lleva sensor crepuscular incorporado, basta con dar tensión y se gestiona solo. Si quieres control manual, instala un interruptor en interior y cablea hacia el proyector."},{"title":"Taladra y fija el soporte del proyector","body":"Marca con lápiz los puntos según la plantilla de fijación. Taladro con broca para el material de la fachada (ladrillo, hormigón, piedra). Tacos M8 mínimo para 50W de peso.","warn":"Si el soporte no queda firme con dos manos, ponle otro taco. Un proyector cayendo desde 3m es peligroso."},{"title":"Conecta los cables al proyector","body":"Abre la caja de conexiones del proyector (suele estar en la parte trasera). Marrón a ''L'' (fase), azul a ''N'' (neutro), verde-amarillo a la toma de tierra (símbolo ⏚). Asegura los prensaestopas con la manguera dentro."},{"title":"Monta el proyector en el soporte y orienta","body":"Encaja el proyector con sus pernos al soporte. Aprieta firme. Orienta el haz hacia el suelo (no horizontal — deslumbra y molesta a vecinos). Da corriente."},{"title":"Sella las entradas de cable con silicona neutra","body":"Por la parte trasera de cualquier perforación que hayas hecho en fachada, aplica silicona neutra (no ácida) para evitar entrada de agua a la caja universal o pared."}],"verification_checks":["El proyector enciende al primer intento, sin parpadeo.","La luz cubre la zona prevista sin deslumbrar a personas a nivel de suelo.","El soporte está firme: mueves el proyector con la mano y no bambolea ni el soporte ni la fijación.","Las entradas de cable están selladas con silicona — el agua de lluvia no debería poder entrar.","Tras 2 horas encendido, el proyector calienta pero no quema al tacto (los LED IP65 disipan bien)."],"problems":[{"summary":"El proyector enciende pero parpadea o se apaga solo","body":"Posible problema de tierra. Verifica con polímetro continuidad desde el cable verde-amarillo del proyector hasta la toma de tierra de tu cuadro. Si no hay continuidad, el proyector está sin tierra y eso desencadena el modo seguridad. Tirar nueva tierra requiere obra."},{"summary":"Salta el diferencial cuando llueve","body":"Entra agua por alguna junta. Vuelve a desmontar, comprueba todas las entradas de cable con prensaestopa apretado y silicona perimetral. Si el problema persiste, el proyector puede tener defecto de fábrica — devuelve en garantía."},{"summary":"El sensor crepuscular no funciona (no se enciende solo de noche)","body":"El sensor del proyector está expuesto a luz parasitaria (otra farola, ventana iluminada). Reorienta para que apunte a zona oscura. Si el problema persiste, el sensor puede tener un potenciómetro de regulación en la parte trasera — ajusta hasta encontrar el punto donde se activa con la luz ambiental correcta."}]}', '2026-05-10', 0),
	(121, 'por-que-parpadea-mi-led', 'Por qué parpadea mi bombilla LED y cómo arreglarlo', 'basica', 'basic', 12, 'Equipo GarperLux', '["89954095","83583729"]', 'Parpadeo a la frecuencia de la red, parpadeo aleatorio o parpadeo solo al apagar: cada síntoma apunta a una causa distinta. Diagnóstico rápido en tres pasos.', 'iluminacion', 'interior', 0, '1585771724684-7b076f6c11ec', 'linear-gradient(135deg, #1C1F26, #B8753A)', '{"hero_eyebrow":"Iluminación","hero_subtitle":"Casi nunca es la bombilla. El parpadeo de un LED tiene tres causas principales: interruptor con piloto luminoso, regulador incompatible o conexión deficiente en el portalámparas. Identificarlo es cuestión de minutos.","intro_paragraphs":["Cuando una LED parpadea, instintivamente cambiamos la bombilla. Y en el 80% de los casos eso NO arregla nada — porque el problema está en la instalación, no en el LED.","Este tutorial te enseña a diagnosticar el origen del parpadeo en tres pasos: observar EL TIPO de parpadeo, comprobar el interruptor y revisar el portalámparas. Después puedes decidir qué pieza cambiar."],"why_section":{"title":"Los tres tipos de parpadeo y qué significa cada uno.","body":"Identifica primero qué tipo de parpadeo ves:","bullets":["<strong>Parpadeo apagada (LED se enciende un instante cada pocos segundos sin estar encendida):</strong> tu interruptor tiene piloto luminoso o regulador no compatible.","<strong>Parpadeo rápido cuando está encendida (50-100 Hz visible):</strong> driver del LED defectuoso o regulador en modo PWM incompatible.","<strong>Parpadeo aleatorio que va y viene:</strong> conexión floja en el portalámparas, casquillo oxidado o contacto sucio."]},"safety_steps":[{"title":"Si vas a abrir el portalámparas, corta corriente","body":"Magnetotérmico del circuito de iluminación."},{"title":"Verifica con polímetro 0V en el casquillo","body":"Modo tensión AC. Sin tensión: vía libre. Con tensión: no es ese circuito."},{"title":"Sin metales, suelo seco","body":"Lo de siempre."},{"title":"Destornillador aislado 1000V si vas a tocar bornes","body":"Si solo cambias bombilla no necesita destornillador, pero ten uno cerca por si hay que apretar."},{"title":"Bombilla fría antes de manipular","body":"Si el LED estaba encendido recién, deja enfriar 30 segundos."}],"when_not":["Hay <strong>varios LED parpadeando en la misma habitación al unísono</strong> — síntoma de problema general (regulador, fase mal). Plantea inspección de instalación.","El parpadeo va acompañado de <strong>zumbido eléctrico audible</strong> — interferencia electromagnética, requiere análisis profesional.","Tras los pasos del tutorial el problema persiste — puede haber un <strong>cortocircuito intermitente</strong> en la caja de registro, requiere técnico.","El LED parpadea Y desprende olor a quemado — para todo, corta corriente, llama a técnico."],"steps":[{"title":"Identifica el tipo de parpadeo","body":"Apunta: ¿es con la luz encendida o apagada? ¿Rápido o lento? ¿Constante o aleatorio? El tipo determina el siguiente paso."},{"title":"Si parpadea APAGADA, revisa tu interruptor","body":"Mira si tu interruptor tiene un punto luminoso (piloto). Esos pilotos dejan pasar microcorriente que el driver del LED detecta. Solución: bombilla \"anti-parpadeo\" (más cara, 6-9€) o desactivar el piloto."},{"title":"Si parpadea ENCENDIDA, revisa si tienes regulador","body":"Si hay regulador (dimmer) en la habitación y tu LED no es regulable, parpadea. Cambia el LED por uno marcado \"dimmable/regulable\" o sustituye el regulador por un interruptor normal.","tip":"Los reguladores antiguos (rotativos) suelen no llevarse bien con LED. Los reguladores modernos universales (Niessen Zenit, Simon Compact) sí."},{"title":"Si parpadea ALEATORIO, revisa el portalámparas","body":"Corta corriente. Saca la bombilla. Mira el contacto central del portalámparas: si está negro o muy aplastado, no hace contacto firme. Limpia con un trapo seco o, en casos extremos, levanta un poco el contacto central con destornillador (suavemente).","warn":"No fuerces el contacto del portalámparas: si lo deformas demasiado, romperás el plástico que lo sujeta."},{"title":"Sustituye el LED por uno nuevo de calidad","body":"Si tras los pasos anteriores aún parpadea, tu LED puede ser defectuoso (mortalidad infantil). Cambia por una marca buena (Philips, Osram, Lexman). Si el LED nuevo NO parpadea, era el LED. Si el nuevo TAMBIÉN parpadea, el problema es de la instalación."},{"title":"Si nada funciona, cambia el portalámparas entero","body":"Cuando el portalámparas está degradado por dentro (no se ve a simple vista), reemplazarlo es 5 minutos de trabajo y 4 euros de pieza. Es la solución más definitiva."}],"verification_checks":["Con luz apagada, la LED queda completamente apagada (ni un destello).","Con luz encendida, la LED es estable (ningún parpadeo visible).","Al encender/apagar varias veces, el comportamiento es siempre el mismo (sin aleatoriedad).","Si tras el cambio del portalámparas o de la bombilla queda estable, sabes con qué te quedas."],"problems":[{"summary":"Cambié la bombilla y la nueva también parpadea","body":"Casi seguro es el interruptor con piloto luminoso. Confirma: ¿el interruptor tiene un puntito que brilla con la luz apagada? Solución: bombilla anti-parpadeo o desactivar el piloto (en algunos modelos se quita un puente interno)."},{"summary":"El parpadeo apareció tras un corte de luz reciente","body":"Posible avería en el driver de la LED por la microsubida de tensión que suele acompañar a los cortes. Cambia el LED. Si el patrón se repite (cortes que matan bombillas), valoraría poner un protector contra sobretensiones en el cuadro."},{"summary":"Solo parpadea cuando enciende también la nevera u otro aparato grande","body":"Microcaída de tensión al arrancar la nevera, suficiente para que el driver de la LED resetee. Si solo dura un segundo y vuelve, no es problema. Si se queda parpadeando, indicaría un cuadro mal dimensionado: consulta técnico."}]}', '2026-05-10', 0),
	(122, 'colocar-plafon-led-techo', 'Colocar un plafón LED de techo sin cortar el cable', 'media', 'medium', 35, 'Alfonso Torres', '["91242444","96149314"]', 'Cambias el plafón viejo por uno LED moderno sin cortar absolutamente nada. El truco está en aprovechar el portalámparas existente y reorganizar la sujeción.', 'iluminacion', 'interior', 0, '1558002038-1055907df827', 'linear-gradient(135deg, #B8753A, #1C1F26)', '{"hero_eyebrow":"Iluminación","hero_subtitle":"Cambiar un plafón de techo es de los trabajos donde más fácil es \"matar\" la instalación. Si sigues el orden correcto, mantienes los cables originales y dejas un plafón LED de 30-40 cm en menos de 40 minutos.","intro_paragraphs":["Un plafón LED de techo da más luz, dura mucho más y queda visualmente más limpio que cualquier plafón antiguo de tornillo+cristal+bombilla. El cambio cuesta unos 25-40€ y la instalación es manejable si trabajas con orden.","El error clásico es cortar los cables del techo \"porque sobran\" — luego no llegan al plafón nuevo. Este tutorial te enseña a NO cortar nunca: usar siempre clemas reutilizables y aprovechar la longitud existente."],"why_section":{"title":"Las ventajas del plafón LED moderno.","body":"Comparado con un plafón clásico (portalámparas + bombilla suelta + cristal embellecedor):","bullets":["<strong>Luz uniforme sin sombras:</strong> el LED en panel difunde mejor que una bombilla central.","<strong>Sin mantenimiento:</strong> 25.000 horas — no cambias bombillas durante 15 años.","<strong>Diseño minimalista:</strong> 2-4 cm de grosor frente a los 12-15 cm del clásico.","<strong>Menos calor:</strong> elimina el riesgo de que la bombilla queme el embellecedor o el techo."]},"safety_steps":[{"title":"Corta el magnetotérmico de iluminación de la zona","body":"Confirmar que es el correcto: pídele a alguien que mire si la luz de esa habitación se apaga, no fiarte de la etiqueta del cuadro."},{"title":"Verifica 0V en los cables del techo con polímetro","body":"Antes de tocar nada, sube a la escalera con polímetro y mide entre los cables que cuelgan del techo. Si tienes 0V, vía libre."},{"title":"Escalera firme, alguien sujeta abajo","body":"Trabajar en techo es trabajar mirando hacia arriba — el equilibrio cambia. No improvisar."},{"title":"Sin anillos, sin pulseras, mangas largas si hay polvo","body":"El polvo del techo cae sobre la cara cuando trabajas hacia arriba. Una gorra y mangas largas te lo ahorran."},{"title":"Destornillador aislado, alicates y clemas reutilizables","body":"Lleva todo el material arriba antes de empezar — bajar a buscar algo a media instalación se traduce en accidentes."}],"when_not":["El plafón viejo está <strong>pegado al techo con resto de pintura</strong> y al despegarlo arrancarías la pintura — requiere lijado posterior.","Los <strong>cables del techo son rígidos y muy cortos</strong> (menos de 5 cm de cable accesible) — riesgo alto de no llegar al plafón nuevo.","El techo es de <strong>pladur de menos de 13 mm</strong> con plafón pesado (>3 kg) — necesitas tacos especiales para pladur o subestructura.","Hay <strong>indicios de humedad en el techo</strong> (manchas, pintura abombada) — antes de plafón nuevo hay que resolver la humedad."],"steps":[{"title":"Quita el plafón antiguo conservando los cables","body":"Afloja el tornillo central o las pestañas laterales del plafón viejo. Bájalo con cuidado: tirará de los cables. Conserva la base del antiguo (el aro fijado al techo) si quieres aprovecharlo."},{"title":"Identifica los cables: fase, neutro y tierra","body":"Marrón/negro = fase. Azul = neutro. Verde-amarillo = tierra (puede faltar en techos antiguos). Si tienes varios cables del mismo color, son retornos a portalámparas adicionales — agrupa con clema."},{"title":"Conecta clemas reutilizables a las puntas","body":"En cada cable del techo, pone una clema Wago tipo \"222\" o similar. Esto te permite añadir y quitar el plafón nuevo sin tocar el aislante.","tip":"Las clemas Wago son reutilizables: levantas la palanca, metes el cable, bajas la palanca. Cuesta 1€ por unidad pero te ahorra horas de futuro."},{"title":"Marca los puntos de anclaje al techo","body":"El plafón nuevo viene con plantilla de fijación. Marca con lápiz dos o tres puntos sobre el techo. Comprueba que NO coinciden con el agujero por donde salen los cables."},{"title":"Taladra y coloca tacos","body":"Broca según material del techo: 6 mm para hormigón con tacos M5, 8 mm con tacos pladur si techo flexible. Inserta los tacos. Si no llegan a fondo, posición incorrecta — vuelve a marcar."},{"title":"Conecta el plafón a las clemas","body":"El plafón LED tendrá tres cables saliendo (marrón, azul, verde-amarillo). Mete cada uno en su clema correspondiente, cierra palanca. Tirón suave de confirmación."},{"title":"Atornilla el plafón al techo y da corriente","body":"Apoya el plafón contra los tacos y atornilla los tornillos suministrados. Comprobar que apoya plano contra el techo (sin ladeo). Sube el magnetotérmico."}],"verification_checks":["El plafón enciende al instante, sin parpadeo.","La luz se difunde uniformemente sobre toda la superficie del plafón (sin zonas más oscuras).","El plafón está firmemente atornillado: no se mueve si lo balanceas con la mano.","El borde del plafón apoya contra el techo sin holgura visible (si hay holgura, ajustar tornillos)."],"problems":[{"summary":"El plafón no encaja contra el techo, queda ladeado","body":"El techo no es perfectamente plano (raro en obra antigua) o los tornillos quedaron más profundos a un lado. Saca los tornillos del lado bajo, mete arandelas extra (1 o 2 mm) y vuelve a atornillar. Quedará nivelado."},{"summary":"Tras encender, el plafón pierde brillo en uno de los lados al cabo de minutos","body":"Síntoma de driver fallando o LED individual mal soldado de fábrica. Es defecto del plafón. Devuelve en garantía. No es nada del cableado tuyo."},{"summary":"Al apagar el plafón se queda con un brillo tenue","body":"Tu interruptor lleva piloto luminoso (microcorriente). Si el plafón es regulable con función \"start glow\" eso lo amplifica. Solución: en el plafón hay un mini-switch o jumper para desactivar el modo low-power. Mira el manual."}]}', '2026-05-10', 0),
	(123, 'entender-cuadro-electrico-domestico', 'Entender tu cuadro eléctrico doméstico sin ser electricista', 'basica', 'basic', 15, 'Alfonso Torres', '["13835080","13835283","19463325"]', 'ICP, IGA, diferencial, magnetotérmicos: lo que hay en tu cuadro y para qué sirve cada cosa. En 15 minutos lo entiendes sin tocar nada.', 'proteccion', 'interior', 0, '1581092918056-87b16d0a4faa', 'linear-gradient(135deg, #DC2626, #1C1F26)', '{"hero_eyebrow":"Protección","hero_subtitle":"Tu cuadro general tiene seis u ocho aparatos que parecen iguales pero hacen cosas muy distintas. Saber identificarlos te permite reaccionar bien cuando salta la luz y saber qué pedir si algo falla.","intro_paragraphs":["El cuadro eléctrico (también llamado cuadro general o caja de magnetotérmicos) es el centro de mando de toda la casa. Allí entra la electricidad de la calle y se reparte en circuitos protegidos: uno para luz, otro para enchufes, otro para cocina, otro para baño...","Entender lo que hay no requiere ser electricista — pero saber distinguir el ICP del IGA, y el diferencial del magnetotérmico, te ahorra hacer el ridículo el día que salta la luz."],"why_section":{"title":"Los cinco aparatos del cuadro estándar.","body":"De izquierda a derecha (o de arriba a abajo según el modelo de cuadro):","bullets":["<strong>ICP (Interruptor de Control de Potencia):</strong> precintado por tu compañía. Salta si superas la potencia contratada.","<strong>IGA (Interruptor General Automático):</strong> tu interruptor manual general. Es el que bajas al irte de vacaciones.","<strong>Diferencial:</strong> protege contra derivaciones a tierra (calambres). Detecta diferencia entre entrada y salida.","<strong>Magnetotérmicos:</strong> uno por circuito. Saltan si hay sobrecarga o cortocircuito.","<strong>Protector contra sobretensiones (opcional):</strong> si lo tienes, protege equipos electrónicos contra picos de tensión."]},"safety_steps":[{"title":"Este tutorial NO requiere tocar el cuadro","body":"Solo abre la tapa, mira y aprende. Sin destornilladores."},{"title":"Si por curiosidad quieres apagar y encender un automático","body":"Hazlo de uno en uno. Bajas, miras qué se apaga, subes. Te enseña qué controla cada uno."},{"title":"Si encuentras algún aparato suelto o desmontado","body":"Para, no toques. Llama a un técnico — el cuadro abierto y manipulable es peligroso."},{"title":"Calzado aislante y suelo seco si vas a abrir la tapa","body":"Aunque no toques, evita rozar accidentalmente con anillos o cadenas."},{"title":"Foto del estado actual antes de tocar nada","body":"Si llamas a un técnico, una foto del cuadro le ahorra tiempo y a ti dinero."}],"when_not":["Hay <strong>aparatos sueltos, no encajados</strong> en el carril DIN.","Ves <strong>cables sueltos colgando</strong> dentro del cuadro.","Hay <strong>olor a quemado o decoloración</strong> en alguno de los aparatos.","El cuadro está <strong>en zona húmeda</strong> (galería sin protección, exterior)."],"steps":[{"title":"Localiza el cuadro y abre la tapa","body":"Habitualmente está cerca de la entrada de la vivienda (hall o cocina). La tapa se abre tirando de la pestaña — algunas tienen llave pequeña."},{"title":"Identifica el ICP","body":"Está PRECINTADO con un sello rojo o azul de la compañía eléctrica. Tú no debes tocar el precinto. El ICP corta toda la vivienda si superas la potencia contratada."},{"title":"Identifica el IGA (interruptor general)","body":"Es el siguiente aparato, normalmente más grande que los demás (40-63 A). Es el que bajas tú cuando vas a hacer un trabajo eléctrico o te vas de vacaciones largas."},{"title":"Identifica el diferencial","body":"Tiene un botón TEST en el cuerpo. Cuando salta, baja por completo de su posición. Suele ser de 25, 40 o 63 A con 30 mA de sensibilidad. Si tu vivienda tiene varios diferenciales, cada uno cubre un grupo de circuitos."},{"title":"Identifica los magnetotérmicos por circuito","body":"Los más pequeños (8-25 A), uno por cada circuito: iluminación, enchufes, cocina, baño, lavadora, aire acondicionado... Léelos: cada uno tiene una etiqueta o sticker indicando qué circuito controla.","tip":"Si las etiquetas son ilegibles o no están, hazlas tú: baja cada magnetotérmico de uno en uno con la nevera funcionando y mira qué se apaga. Apunta con pegatinas."},{"title":"Mira si tienes protector contra sobretensiones","body":"Es un aparato un poco más grueso, con indicador visual (LED verde si está bien, rojo si ha actuado). No todas las viviendas lo tienen — es recomendable si hay tormentas frecuentes o tienes equipos sensibles (PC, TV, sistemas domóticos)."}],"verification_checks":["Identificas el ICP, IGA, diferencial y magnetotérmicos sin confundirlos.","Sabes qué circuito cubre cada magnetotérmico (o has hecho la prueba de bajarlos para descubrirlo).","Si tienes diferencial, has localizado su botón TEST.","Conoces la potencia contratada (figura en la factura) y la potencia indicada en el ICP."],"problems":[{"summary":"¿Qué hago si salta solo el ICP?","body":"Estás superando tu potencia contratada. Apaga el aparato que más consume (placa de inducción, secador, horno) y vuelve a subir el ICP. Si te pasa a menudo, valora si contratar más potencia (llamada a tu compañía) o repartir mejor las cargas."},{"summary":"¿Qué hago si salta el diferencial?","body":"Algo del circuito está derivando a tierra: aparato con cable pelado, humedad en una caja, electrodoméstico con fuga. Sube el diferencial. Si vuelve a saltar: baja todos los magnetotérmicos, sube el diferencial, sube magnetotérmicos uno a uno hasta que salte otra vez. Ese circuito tiene el problema."},{"summary":"¿Qué hago si salta un magnetotérmico?","body":"Sobrecarga (demasiados aparatos a la vez en ese circuito) o cortocircuito (cable haciendo contacto donde no debe). Desconecta lo que tengas enchufado en ese circuito, sube el magnetotérmico. Si aguanta y vuelve a saltar cuando enchufas algo, ese aparato tiene problema."}]}', '2026-05-10', 0),
	(124, 'cortar-luz-del-circuito-correcto', 'Cómo cortar la luz del circuito correcto', 'basica', 'basic', 12, 'Alfonso Torres', '["13835080"]', 'Bajar el general es opción, pero deja toda la casa a oscuras. Identificar y bajar SOLO el magnetotérmico del circuito en cuestión es la pro-move.', 'proteccion', 'interior', 0, '1581092918056-87b16d0a4faa', 'linear-gradient(135deg, #DC2626, #1C1F26)', '{"hero_eyebrow":"Protección","hero_subtitle":"Antes de cualquier trabajo eléctrico hay que cortar la corriente. Pero cortarla toda — bajar el IGA — te deja sin nevera, sin Wi-Fi y sin luz para trabajar. Cortar solo el circuito afectado es la opción profesional.","intro_paragraphs":["Cada circuito de tu casa tiene un magnetotérmico dedicado en el cuadro: iluminación, enchufes de salón, cocina, lavadora, baño... Bajar solo el correcto te deja trabajar con seguridad y mantiene el resto de la casa operativa.","El problema es que las etiquetas del cuadro suelen ser ilegibles, estar mal puestas o directamente no existir. Este tutorial te enseña a identificar el circuito en 12 minutos para que la próxima vez sepas exactamente cuál bajar."],"why_section":{"title":"Por qué NO conviene bajar el IGA general.","body":"Cortar todo es el reflejo fácil, pero tiene costes:","bullets":["<strong>Pierdes la nevera y el congelador:</strong> si te llevas más de 2-3 horas, el frescor empieza a sufrir.","<strong>Pierdes la conexión Wi-Fi y la TV:</strong> útil si necesitas consultar el tutorial mientras trabajas.","<strong>Pierdes la iluminación de la zona donde trabajas:</strong> tienes que improvisar con linterna o luz natural.","<strong>Reseteas relojes y termostatos:</strong> al volver tendrás que reprogramar."]},"safety_steps":[{"title":"Llevas polímetro siempre","body":"Confirmar AUSENCIA de tensión es el último paso, no opcional."},{"title":"Trabajas con una sola mano si puedes","body":"Mantén la otra en el bolsillo o detrás. Reduces riesgo de cierre de circuito por tu cuerpo."},{"title":"Calzado aislante","body":"Suelo seco y aislante en lo posible."},{"title":"Si llamas a alguien para que verifique mientras trabajas","body":"Aseguraos de que no hay otros automáticos automáticos rearmados que repongan corriente sin avisar."},{"title":"Foto del cuadro antes de tocar","body":"Por si quieres recordar la posición de cada interruptor (algunos pueden estar habitualmente en posición OFF si están desconectados)."}],"when_not":["El cuadro <strong>no tiene magnetotérmicos individuales</strong> sino fusibles antiguos — instalación pre-1970, llamar técnico.","Las <strong>etiquetas son tan malas</strong> que prefieres cortar todo a perder media hora identificando.","Solo hay <strong>un magnetotérmico para todo</strong> el piso (frecuente en pisos pequeños o muy antiguos): no queda otra que cortar todo.","El cuadro está en <strong>zona común</strong> (rellano) y no puedes manipularlo libremente."],"steps":[{"title":"Conecta una carga al circuito que vas a aislar","body":"Si vas a trabajar en un interruptor, enciende esa luz. Si vas a trabajar en un enchufe, enchufa una lámpara o cargador con luz."},{"title":"Sitúate cerca del cuadro general","body":"Si trabajas solo, lleva el móvil con linterna por si todo se pone oscuro."},{"title":"Baja los magnetotérmicos de uno en uno","body":"Empieza por el primero (excluyendo ICP e IGA). Mira o pide que te avisen si la luz/lámpara se ha apagado. Si no, sube ese magnetotérmico y prueba el siguiente.","tip":"Esto se hace MUCHO más rápido si tienes ayuda: una persona en el cuadro, otra en la zona de trabajo, con teléfono abierto entre ambos."},{"title":"Cuando localizas el magnetotérmico correcto, déjalo abajo","body":"Ese es el que vas a mantener abajo durante el trabajo. Pega un pequeño cartel encima diciendo \"EN OBRA - NO SUBIR\" si vives con más gente."},{"title":"Sube todos los demás","body":"El resto de circuitos puede volver a funcionar normalmente."},{"title":"Verifica con polímetro AUSENCIA de tensión","body":"En el punto donde vas a trabajar, mide entre fase y neutro: debe marcar 0V. Si no, has identificado mal — vuelve al cuadro."}],"verification_checks":["El polímetro marca 0V en el punto de trabajo.","La carga de prueba (lámpara, cargador) sigue apagada al subir todos los demás magnetotérmicos.","El resto de la casa funciona con normalidad.","El cartel \"EN OBRA\" está visible si vives acompañado."],"problems":[{"summary":"Bajo un magnetotérmico y NO se apaga la luz/lámpara de prueba","body":"Ese circuito no controla lo que crees. Súbelo y prueba el siguiente. Si has probado todos: revisa que la carga de prueba esté realmente conectada — quizás se ha aflojado."},{"summary":"Bajo un magnetotérmico y se apagan varias cosas a la vez","body":"Ese circuito agrupa varios puntos: enchufes de varias habitaciones o luz+enchufe juntos. Es normal en cuadros antiguos. Puede ser el que necesitas, pero plantéate si quieres trabajar sin el resto de cosas que dependen de él."},{"summary":"He bajado el correcto pero el polímetro sigue marcando tensión","body":"Mide cuidadosamente: ¿estás midiendo entre fase y neutro O entre fase y tierra? Si estás midiendo entre cualquier cable y tierra y marca tensión, hay un retorno por neutro mal aislado — para todo y llama técnico."}]}', '2026-05-10', 0),
	(125, 'usar-polimetro-sin-miedo', 'Usar un polímetro sin miedo: las 3 medidas básicas', 'basica', 'basic', 18, 'Equipo GarperLux', '["90348616"]', 'Tensión, continuidad y resistencia: las tres medidas que necesitas saber para ser autónomo en cualquier reparación eléctrica menor. 18 minutos de aprendizaje que te resuelven la vida.', 'proteccion', 'interior', 0, '1607082352121-fa243f3dde32', 'linear-gradient(135deg, #40454F, #1C1F26)', '{"hero_eyebrow":"Protección","hero_subtitle":"Un polímetro digital cuesta entre 8 y 30 euros y es la pieza más importante de cualquier kit de bricolaje eléctrico. Saber usarlo en sus tres modos básicos (tensión, continuidad, resistencia) te hace autónomo en el 90% de las situaciones.","intro_paragraphs":["El polímetro (también llamado multímetro) mide magnitudes eléctricas. Hay decenas de funciones en los modelos avanzados, pero el doméstico solo necesita tres: medir tensión (¿llega corriente?), medir continuidad (¿este cable pasa señal de un extremo al otro?) y medir resistencia (¿este componente tiene el valor esperado?).","El miedo a los polímetros viene de no entender qué significan los símbolos. Este tutorial te lo aclara en 18 minutos."],"why_section":{"title":"Las tres medidas que vas a usar el 90% del tiempo.","body":"Aprende estas tres y te llega para todo:","bullets":["<strong>Tensión AC (símbolo V~):</strong> ¿hay 230V en este enchufe? Es la medida de seguridad antes de tocar nada.","<strong>Continuidad (símbolo de bocina o diodo):</strong> ¿el cable está sano de extremo a extremo? El polímetro suena (\"beep\") si hay paso.","<strong>Resistencia (símbolo Ω):</strong> ¿esta bombilla está fundida? ¿este fusible está bueno? Mide la resistencia del componente."]},"safety_steps":[{"title":"Antes de medir tensión, ajusta el selector al rango ADECUADO","body":"Si vas a medir 230V (red doméstica) selecciona escala V~ (AC) en 600V o automático. Nunca midas tensión en escala de resistencia (Ω) — puedes dañar el polímetro."},{"title":"Cables de prueba en los conectores correctos","body":"El cable NEGRO va al conector COM (común). El cable ROJO va al conector V/Ω/mA para medidas hasta 400 mA — o al conector 10A si vas a medir corriente alta (raro en doméstico)."},{"title":"Si vas a medir tensión, NUNCA toques las puntas metálicas","body":"Solo el plástico aislado. Aunque las puntas estén aisladas, los 230V queman si tocas mal."},{"title":"Polímetro con pilas en buen estado","body":"Si el polímetro tiene la batería baja, las medidas pueden ser erróneas. Cambia la pila si la pantalla muestra el icono de batería baja."},{"title":"Si no estás seguro de qué tipo de tensión hay (AC o DC), ESPERA","body":"Mide primero en DC; si marca 0, prueba en AC. Pero nunca midas con la escala equivocada — los modernos están protegidos pero los baratos no."}],"when_not":["Vas a medir corrientes <strong>superiores a 10A</strong> — necesitas pinza amperimétrica, no polímetro.","Vas a medir <strong>en una placa electrónica energizada</strong> — riesgo de cortocircuitarla con las puntas.","El polímetro <strong>tiene los cables sin aislante</strong> en alguna parte — cómprate cables nuevos antes de usarlo.","Vas a usar el polímetro en <strong>instalaciones industriales (380V trifásica)</strong> — necesitas equipo categoría CAT IV adecuado."],"steps":[{"title":"Familiarízate con el selector y los conectores","body":"Selector central: gira a las distintas funciones. Identifica V~ (tensión AC), V⎓ (tensión DC), Ω (resistencia), continuidad (bocina). Conectores: COM (negro) siempre; V/Ω (rojo) para casi todo."},{"title":"MEDIDA 1: Tensión en un enchufe","body":"Selector en V~ (escala 600 o automático). Cables: negro en COM, rojo en V/Ω. Introduce las dos puntas (con cuidado, con plástico) en los dos agujeros del enchufe. Debe marcar 220-240V. Si marca 0V, ese enchufe está sin tensión."},{"title":"MEDIDA 2: Continuidad de un cable","body":"Selector en posición de bocina (símbolo de altavoz o diodo). Cables en COM y V/Ω. Junta las dos puntas: debe sonar \"beep\" — eso confirma que tu polímetro detecta continuidad. Ahora pon una punta en cada extremo del cable que quieres testar. Si suena: cable bueno. Si no suena: cable roto o roto-mal-empalmado.","tip":"La continuidad la usas mucho: para saber si una bombilla está fundida, si un fusible está bueno, si un cable largo no se ha roto a mitad de recorrido."},{"title":"MEDIDA 3: Resistencia (Ω)","body":"Selector en Ω. Cables como antes. Punta a cada lado del componente que quieres medir. La pantalla muestra los ohmios. Un fusible bueno marca ≈0 Ω. Una resistencia marcada \"100Ω\" debe marcar 95-105 Ω. Un cable bueno también ≈0 Ω."},{"title":"PRACTICA: prueba a verificar si una bombilla está fundida","body":"Saca la bombilla. Selector en continuidad. Una punta al casquillo metálico (rosca) y otra al contacto central inferior. Si suena: bombilla buena. Si no suena: filamento o LED interno roto, fundida."},{"title":"Apaga el polímetro al terminar","body":"Selector en posición OFF. Si tu polímetro es \"auto-power-off\" se apaga solo a los 5-15 minutos. Pero apagarlo manualmente alarga la batería."}],"verification_checks":["Sabes identificar las tres posiciones del selector (V~, continuidad, Ω) sin dudar.","Has medido tensión en un enchufe vivo y has obtenido 220-240V.","Has confirmado continuidad de un cable sano y ausencia de continuidad de uno roto.","Has medido la resistencia de un fusible y comprobado si está bueno (≈0 Ω) o quemado (∞)."],"problems":[{"summary":"Mido tensión y la pantalla no marca nada o marca \"OL\"","body":"OL significa \"overload\" (fuera de rango) o no ha detectado tensión. Verifica: ¿está el selector en V~ (AC) y no en V⎓ (DC)? ¿Están los cables en COM y V/Ω respectivamente? ¿Las puntas hacen contacto firme dentro del enchufe? Si todo está bien y aún marca OL, prueba en otro enchufe que sepas que funciona para descartar problema del polímetro."},{"summary":"La continuidad suena siempre, incluso con las puntas separadas","body":"El polímetro tiene una avería interna o el selector no está realmente en continuidad (es fácil pasarse de la posición). Mueve el selector con cuidado a la posición exacta. Si persiste, el polímetro está defectuoso."},{"summary":"Mido resistencia de un cable largo y no marca 0 Ω, marca 1-2 Ω","body":"Es normal. Los cables tienen una pequeña resistencia residual por su longitud. Un cable de 10 m con sección 1,5 mm² puede dar 0,1-0,3 Ω. Si supera los 5-10 Ω, ese cable tiene un problema (oxidación, empalme malo). Si marca infinito, el cable está roto."}]}', '2026-05-10', 0),
	(127, 'herramientas-imprescindibles-electricista', 'Herramientas imprescindibles para el electricista doméstico', 'basica', 'basic', 10, 'Alfonso Torres', '["90348616"]', 'Las 8 herramientas básicas para resolver el 95% de los trabajos en tu casa. No necesitas un taller — un cajón ordenado vale.', 'fundamentos', 'interior', 0, '1607082352121-fa243f3dde32', 'linear-gradient(135deg, #E4DCCA, #B8753A)', '{"hero_eyebrow":"Fundamentos","hero_subtitle":"Antes de cualquier tutorial conviene tener el kit mínimo. Estos 8 elementos cubren todos los trabajos eléctricos domésticos sin pretensión profesional. Te los puedes hacer con 60-90 euros en total.","intro_paragraphs":["El sentido común dice: \"tengo destornilladores, ¿para qué más?\" — y luego uno se encuentra con que el destornillador es plano cuando hace falta de estrella, o que no tiene polímetro y trabaja a ciegas.","Este es el kit que recomiendan los instaladores autorizados para Hazlo Tú Mismo. Cómpralo de una vez, ordénalo en un cajón o caja, y tendrás respuesta para casi todo."],"why_section":{"title":"Por qué ESTE kit y no más.","body":"El error común es comprar un kit \"profesional\" de 60 piezas que no usarás. Mejor pocas herramientas, buenas, y bien clasificadas:","bullets":["<strong>Polímetro:</strong> imprescindible para verificar ausencia de tensión.","<strong>Destornillador aislado 1000V (plano + estrella):</strong> para todos los tornillos de mecanismos.","<strong>Alicates universales y de corte:</strong> uno multiusos para todo, otro específico de corte.","<strong>Pelacables:</strong> pelar 8 mm sin dañar el cobre es un arte.","<strong>Buscapolos:</strong> el viejo truco para detectar fase sin sacar polímetro.","<strong>Cinta aislante:</strong> imprescindible.","<strong>Linterna frontal:</strong> trabajar con las dos manos libres es otro nivel.","<strong>Una caja o cajón ordenado:</strong> que no se te pierdan."]},"safety_steps":[{"title":"El destornillador aislado 1000V NO es opcional","body":"No comprar un destornillador normal pensando \"si corto la corriente da igual\". El aislado vale 6-8 euros y te salva el dedo el día que cortes mal."},{"title":"El polímetro categoría CAT III mínimo","body":"CAT III es la categoría de seguridad mínima para uso doméstico en circuitos hasta 600V. CAT II es para electrónica, no enchufes."},{"title":"Los alicates con mangos aislados a 1000V","body":"Mismo principio que el destornillador. La etiqueta debe poner explícitamente \"1000V\" o \"VDE\"."},{"title":"Guarda las herramientas en sitio limpio y seco","body":"El óxido en las puntas del polímetro o en la rosca del destornillador degrada la herramienta y puede afectar a las medidas."},{"title":"Revisa el aislamiento de los cables del polímetro de vez en cuando","body":"Si ves grietas o pelados, cambia los cables (cuestan 5-10 euros) o el polímetro entero."}],"when_not":["Vas a hacer trabajos <strong>en alta densidad de circuitos</strong> (taller, cuadro general grande): necesitas más herramientas específicas.","Vas a trabajar <strong>cables de gran sección</strong> (>4 mm²) — los alicates universales no pueden con ellos, necesitas crimpadora.","Trabajos con <strong>tubo metálico o canalización industrial</strong> — necesitas cortatubos y herramienta de instalador profesional.","Si vives en piso alquilado y prevés trabajos puntuales, igual <strong>contratar técnico</strong> es más rentable que comprar el kit."],"steps":[{"title":"Polímetro digital","body":"UNI-T A03 o similar, 8-15 euros. Categoría CAT III mínimo. Auto-rango facilita la vida (no tienes que elegir escala manualmente). Pilas alcalinas duraderas.","tip":"Hay polímetros más caros con tester de continuidad rápido y NCV (detector de tensión sin contacto). Si te lo puedes permitir, esa función NCV es muy útil."},{"title":"Destornilladores aislados 1000V","body":"Plano de 3-4 mm y estrella PH1 son suficientes. Wera, Wiha, Bahco son marcas reconocidas. Una marca \"Toolcraft\" de tienda local también vale si está etiquetada 1000V."},{"title":"Alicates universales y de corte","body":"Universales para sujetar y manipular. De corte específico (cortafríos) para pelar manguera o cortar cable. Mangos rojos = aislamiento 1000V verificado."},{"title":"Pelacables","body":"Modelo automático que regula solo la apertura para no dañar el cobre. Hay desde 7€ (genérico) hasta 35€ (Knipex profesional). Para uso doméstico, uno de 12€ vale."},{"title":"Buscapolos (tester de fase)","body":"El destornillador pequeño con luz que se enciende cuando tocas la fase. No sustituye al polímetro pero es complemento rápido. UNI-T tiene un modelo con buscapolos integrado en un cuerpo robusto.","warn":"El buscapolos solo detecta FASE (no neutro ni tierra). Para confirmar ausencia de tensión sigues necesitando polímetro."},{"title":"Cinta aislante y clemas Wago","body":"Cinta aislante de PVC (color negro o color identificativo). Clemas Wago reutilizables (modelo 222 o 221) para empalmes limpios sin soldadura."},{"title":"Linterna frontal","body":"10-20 euros. LED con batería, idealmente recargable USB. Trabajar con las dos manos libres mirando techo o caja de registro mejora todo."},{"title":"Caja organizadora","body":"Cualquier caja con compartimentos (tipo organizador de tornillos). Etiqueta cada cosa o ten al menos zonas dedicadas: medidas, atornilladores, pelado, conexión."}],"verification_checks":["Tienes todas las 8 herramientas en una caja accesible.","El polímetro tiene pilas con carga y los cables en buen estado.","Los destornilladores aislados llevan la etiqueta 1000V/VDE visible.","Sabes la ubicación de la caja sin pensar — no buscarla en momentos de emergencia."],"problems":[{"summary":"Mi pelacables no pela bien, deja melladuras en el cobre","body":"La cuchilla del pelacables está mal regulada o ha perdido filo. Si es regulable, ajusta la profundidad. Si está fija, cámbiala (algunos modelos permiten cambio de cuchilla). Si tu pelacables es de 5€, valora subir a uno de 15€ — la diferencia se nota mucho."},{"summary":"Mi destornillador aislado dejó de aislar (vino con un golpe)","body":"Si el plástico del mango tiene grieta visible, NO uses ese destornillador para trabajo eléctrico. Cómpralo nuevo. Las grietas no se pueden \"arreglar\" con cinta — el aislamiento dieléctrico necesita continuidad perfecta."},{"summary":"Las clemas Wago me parecen caras y prefiero soldar","body":"Las clemas Wago tipo 222 cuestan 1-1,5€ por unidad pero te ahorran soldar, son reutilizables y aguantan hasta 4 mm². Soldar empalmes eléctricos en una caja de registro es peor solución (uniones rígidas que se rompen con vibración). Las Wago son el estándar moderno."}]}', '2026-05-10', 0),
	(128, 'domotizar-interruptor-shelly-1mini', 'Domotizar un interruptor con Shelly 1 Mini', 'media', 'medium', 45, 'Pedro Ramírez', '["95928664","14787801"]', 'Mismo interruptor de toda la vida, pero ahora también lo enciendes desde Alexa o el móvil. El relé Shelly 1 Mini cabe DETRÁS del mecanismo existente.', 'domotica', 'interior', 0, '1556017011-26ce2c7a3a9e', 'linear-gradient(135deg, #1E3A8A, #0B0D12)', '{"hero_eyebrow":"Domótica","hero_subtitle":"Un módulo Shelly 1 Mini Gen4 es un relé Wi-Fi del tamaño de una moneda que se instala detrás del interruptor existente. Mantienes la tecla física y, además, puedes controlar la luz por app, asistente de voz o automatización. Es la entrada más limpia al mundo de la domótica.","intro_paragraphs":["Shelly se ha convertido en el estándar de facto para domotizar viviendas existentes. No requiere hub, no obliga a usar la nube y la integración con Alexa/Google/Home Assistant es robusta. El módulo cuesta 17 euros y se instala en menos de una hora.","El requisito clave: la caja universal donde va el interruptor debe tener NEUTRO (cable azul). Las instalaciones modernas (1990 en adelante) lo tienen casi siempre. Las muy antiguas pueden no tenerlo y entonces Shelly 1 Mini no funciona — usar el modelo Shelly 1 Mini sin neutro o un Plus 1."],"why_section":{"title":"Por qué Shelly funciona donde otros fallan.","body":"Comparado con bombillas inteligentes o enchufes Wi-Fi:","bullets":["<strong>Conservas la tecla física:</strong> familiares e invitados encienden la luz \"a la antigua\" sin saber que es domótica.","<strong>No necesita hub:</strong> conecta directo al Wi-Fi de tu router.","<strong>Cloud opcional:</strong> puedes usarlo solo en red local (Home Assistant) o con su nube.","<strong>Funciona con cualquier bombilla:</strong> halógena, LED, fluorescente. No es la bombilla la que es inteligente.","<strong>Compatibilidad multi-plataforma:</strong> Alexa, Google Home, HomeKit (vía bridge), Home Assistant, Matter."]},"safety_steps":[{"title":"Corta el circuito de iluminación en el cuadro","body":"Magnetotérmico de la zona. Verifica que la luz que vas a domotizar se apaga."},{"title":"Verifica con polímetro 0V en la caja","body":"Mide entre cualquier par de cables: 0V. Sin tensión = vía libre."},{"title":"Sin metales en manos, suelo seco","body":"Lo de siempre."},{"title":"Destornillador aislado 1000V","body":"Sin excepción."},{"title":"Foto del cableado antes de tocar","body":"Especialmente importante con Shelly, donde añades un componente más al circuito."}],"when_not":["Tu caja universal <strong>NO tiene neutro</strong> (3 cables o menos: solo fase + retornos) — necesitas modelo Shelly 1 Mini sin neutro o instalación de neutro hasta esa caja.","La caja universal está <strong>llena</strong> y no entra el módulo: pliega cables con cuidado o cambia a una caja universal de 60 mm más profunda.","Tu Wi-Fi <strong>no llega bien</strong> a la zona donde está el interruptor: prueba la cobertura con el móvil antes de comprar.","Vives en piso alquilado y el contrato <strong>prohíbe modificaciones eléctricas</strong> — algunos contratos lo prohíben explícitamente."],"steps":[{"title":"Desmonta el mecanismo existente","body":"Tecla, marco, garras. Saca el interruptor unos centímetros sin desconectar todavía. Toma foto."},{"title":"Identifica fase, neutro y retornos","body":"Fase (marrón/negro): la entrada al interruptor. Neutro (azul): debe existir en la caja, NO conectado al interruptor original (porque un interruptor monopolar no usa neutro). Retorno (negro/gris/marrón): el cable que va al portalámparas."},{"title":"Conecta los cables al Shelly según el esquema","body":"Shelly 1 Mini Gen4 lleva 4 bornes: L (fase de entrada), N (neutro), O (salida al portalámparas), I (botón/interruptor). El esquema es: fase de la red → L. Neutro → N. Borne O → al portalámparas (retorno). Botón I → al interruptor (pasamos por la tecla). Lleva impreso en el chasis del Shelly.","tip":"Si tu interruptor era unipolar simple, debes pasar el cable de retorno por el Shelly: ya NO va directo al portalámparas, va al borne O del Shelly. El borne I del Shelly conecta al borne del interruptor que antes recibía la entrada."},{"title":"Mete el módulo Shelly en la caja universal","body":"El Shelly 1 Mini Gen4 mide ~36 × 39 × 17 mm. Cabe detrás de un interruptor estándar. Coloca el módulo PRIMERO en el fondo de la caja, dobla los cables sin pillarlos, y encima coloca el interruptor original (con sus cables al borne I y a la fase).","warn":"Asegúrate de que ningún cable está pelado dentro de la caja. Si has pelado de más al conectar, recorta y vuelve a pelar 8 mm."},{"title":"Atornilla las garras del mecanismo y prueba físicamente","body":"Aprieta las dos garras alternando. Coloca marco y tecla. Sube el magnetotérmico. Acciona la tecla: debe encender la luz como antes."},{"title":"Conecta el Shelly a tu Wi-Fi","body":"Abre la app Shelly Smart Control (Android/iOS). Pulsa ''Add device''. Sigue el asistente: el Shelly emite su propio Wi-Fi temporal al que conectas, das credenciales de tu Wi-Fi doméstico, y a los 30 segundos aparece en la app. Renombra como quieras (\"Luz salón\", \"Luz cocina\")."},{"title":"Vincula con Alexa o Google si quieres voz","body":"En la app Alexa: Skills > Shelly Smart Control > vincular. En Google Home: Servicios > Shelly. Pide a Alexa/Google reconocer dispositivos. Ya puedes decir \"Alexa, enciende la luz del salón\"."}],"verification_checks":["La tecla física enciende y apaga la luz como siempre.","Desde la app Shelly enciendes/apagas la luz a distancia.","El asistente de voz responde al comando \"enciende [nombre]\".","El estado de la luz en la app refleja el estado real (si la enciendes con la tecla, la app lo muestra)."],"problems":[{"summary":"La tecla funciona pero la app no controla la luz","body":"El Shelly no está conectado al Wi-Fi o está conectado pero perdió enlace. Revisa la app: ¿aparece online o offline? Si offline, vuelve a vincular siguiendo el asistente. Si online pero no responde, reinicia el módulo cortando el magnetotérmico 10 segundos y volviendo a subir."},{"summary":"La luz parpadea al encender desde la app","body":"Es habitual con bombillas LED de bajo coste y relés mecánicos. El Shelly hace ''click'' al cerrar el contacto. La LED puede parpadear durante el arranque. Si te molesta, usa LED de marca buena con driver estable."},{"summary":"Al apagar desde la app, la luz queda con brillo tenue","body":"Similar al efecto del piloto luminoso del interruptor: una microcorriente fluye por el circuito. Solución: bombilla LED \"anti-parpadeo\" o cambiar el modelo de Shelly a uno con función de aislamiento total (Shelly Plus 1)."}]}', '2026-05-10', 0),
	(129, 'instalar-detector-agua-wifi-fugas', 'Instalar detectores Wi-Fi para gas, humo y agua', 'basica', 'basic', 20, 'Pedro Ramírez', '["92169429","92169427","95928660"]', '20 euros y 20 minutos para evitar inundaciones. El detector va bajo la lavadora, lavavajillas o caldera y te avisa al móvil al primer contacto con agua.', 'domotica', 'interior', 0, '1556017011-26ce2c7a3a9e', 'linear-gradient(135deg, #1E3A8A, #B8753A)', '{"hero_eyebrow":"Domótica","hero_subtitle":"Un detector de agua Wi-Fi es la mejor inversión preventiva en domótica. Cuesta 15-25 euros, lo colocas en 20 minutos sin obra y te avisa al móvil si detecta agua donde no debería haberla. Salva del desastre.","intro_paragraphs":["Las inundaciones domésticas más caras NO vienen de un grifo abierto — vienen de mangueras de lavadora rotas, descargas accidentales del lavavajillas, calderas con fugas pequeñas o tubos del aire acondicionado obstruidos. Cualquiera de esos casos puede pasar 4 días desapercibido y arruinar suelos, muebles y techos del vecino de abajo.","El detector de agua Wi-Fi es un sensor que reconoce el contacto con agua y manda push al móvil. No requiere cableado, funciona con pilas (1-2 años) y se vincula a la red Wi-Fi doméstica en cinco minutos."],"why_section":{"title":"Las cuatro ubicaciones críticas.","body":"Donde poner los detectores prioritariamente:","bullets":["<strong>Bajo la lavadora o lavavajillas:</strong> las mangueras de entrada se rompen con poco aviso.","<strong>Junto a la caldera de gas o termo eléctrico:</strong> goteo lento por sales acumuladas.","<strong>Bajo el lavabo del baño o cocina:</strong> juntas de sifón degradadas son habituales.","<strong>En la salida de condensación del aire acondicionado:</strong> el desagüe se obstruye con polvo y rebosa."]},"safety_steps":[{"title":"Detector con pilas listas (suministradas o no)","body":"Algunos modelos vienen con pila preinstalada protegida por una pestaña de plástico. Si la tuya viene aparte, ponla siguiendo la polaridad indicada."},{"title":"Pon en marcha el detector ANTES de colocarlo","body":"Confírmalo: enciende, parpadea LED, suena beep de inicialización. Si no responde, las pilas están agotadas o mal puestas."},{"title":"Coloca con orientación correcta","body":"Los sensores van en la parte INFERIOR del detector (los puntos metálicos visibles). Si lo pones con sensores hacia arriba, no detectará agua del suelo."},{"title":"Wi-Fi de 2,4 GHz disponible","body":"Los detectores Wi-Fi domésticos generalmente solo soportan 2,4 GHz (no 5 GHz). Si tu router emite solo 5 GHz, activa también la red 2,4."},{"title":"App del fabricante instalada en el móvil","body":"Tuya Smart, Smart Life o la app específica del fabricante. La app gestiona la vinculación y las notificaciones."}],"when_not":["El sitio donde quieres ponerlo está <strong>permanentemente húmedo</strong> (zona de duchas con condensación) — daría falsos positivos constantes.","El detector va en <strong>zona sin cobertura Wi-Fi</strong> — los avisos no llegarían al móvil.","Tu casa no tiene <strong>llave de paso accesible</strong> que puedas cerrar rápido cuando llega el aviso — el detector avisa pero no para el agua.","Vives en piso de alquiler con <strong>operativa de fugas a cargo del propietario</strong> — coordina la instalación."],"steps":[{"title":"Saca el detector del embalaje","body":"El kit incluye: detector con sensores integrados, pilas (a veces preinstaladas), manual rápido. Algunos modelos vienen con una sonda externa adicional con cable de 1-2m para llegar a sitios estrechos."},{"title":"Coloca las pilas","body":"Abre la tapa trasera. Pon las pilas siguiendo la polaridad (+ y -). Cierra. El detector emite un beep o un parpadeo de LED al arrancar."},{"title":"Instala la app y crea cuenta","body":"Tuya Smart, Smart Life o equivalente según fabricante. Crea cuenta con email y verifica con código."},{"title":"Vincula el detector a la app","body":"En la app: pulsa ''+'', selecciona ''Sensor de agua'' o ''Añadir dispositivo''. La app pedirá credenciales Wi-Fi y guiará el proceso de vinculación. El detector entrará en modo emparejamiento (LED parpadeando rápido).","tip":"Si la vinculación falla, mantén pulsado el botón del detector durante 5 segundos hasta que el LED parpadee más rápido (modo emparejamiento manual)."},{"title":"Configura las notificaciones push","body":"En la app, dentro del detector, abre la sección ''Notificaciones'' o ''Alertas''. Activa ''Notificación push''. Considera también activar ''SMS'' o ''Llamada automática'' si el fabricante lo permite — útil si el push no te llega (móvil silenciado por la noche)."},{"title":"Prueba con una gota de agua","body":"Antes de dejarlo en su sitio, prueba: humedece los sensores metálicos con un dedo mojado. En 3-10 segundos debería sonar la alarma del detector y llegar la push al móvil."},{"title":"Coloca el detector en su ubicación final","body":"Sensores hacia abajo, en contacto con el suelo. Si el sitio es muy estrecho (debajo de la lavadora), usa la sonda externa con cable que viene con algunos modelos. La unidad principal queda en zona accesible para sustituir pilas."}],"verification_checks":["El detector emite la alarma cuando los sensores tocan agua.","La notificación push llega al móvil en menos de 30 segundos.","El nivel de batería se muestra en la app (debe estar al 100% recién puesto).","Conoces la ubicación exacta de la llave de paso para cerrar el agua cuando llegue el aviso."],"problems":[{"summary":"El detector pita pero no me llega notificación al móvil","body":"Revisa la configuración de la app: las notificaciones push deben estar activadas. Revisa la configuración del móvil: la app debe tener permiso para notificaciones (Ajustes > Apps > [App] > Notificaciones). Si usas modo silencio o no-molestar, las notificaciones pueden quedar bloqueadas."},{"summary":"Pita en falso (sin agua aparente)","body":"Humedad ambiental alta + polvo sobre los sensores hace falsos positivos. Limpia los sensores con un paño seco. Si persiste, mueve el detector a zona menos polvorienta."},{"summary":"Las pilas duran solo 3 meses cuando deberían durar 1 año","body":"El detector pierde mucha energía si está constantemente fallando vinculación con el Wi-Fi. Asegúrate de que la cobertura es estable en su ubicación. Si el Wi-Fi va y viene, el detector consume al intentar reconectar. Usa pilas de marca (Energizer, Duracell) — las low-cost duran mucho menos."}]}', '2026-05-10', 0),
	(130, 'tirar-manguera-3x15-falso-techo', 'Tirar manguera 3x1,5 por falso techo', 'avanzada', 'high', 90, 'Alfonso Torres', '["17915884"]', 'Pasar manguera nueva entre dos puntos sin abrir paredes. Requiere falso techo accesible, pasacables y paciencia — pero ahorras una obra de albañilería.', 'cableado', 'interior', 0, '1558618666-fcd25c85cd64', 'linear-gradient(135deg, #B8753A, #1C1F26)', '{"hero_eyebrow":"Cableado","hero_subtitle":"Si tu vivienda tiene falso techo en pasillos o salones, ese hueco es la autopista de cables ideal para añadir nuevos puntos de luz o llevar alimentación a un proyector exterior. Si te organizas, evitas regatas y obra de albañilería.","intro_paragraphs":["Una manguera 3x1,5 mm² (fase + neutro + tierra) es la sección estándar para circuitos de iluminación. Tirarla por el falso techo es trabajo de bricolaje avanzado que ahorra hacer rozas a pico y pala — pero requiere herramienta básica (pasacables, guía) y entender por dónde puedes y no puedes pasar.","Este tutorial cubre el caso típico: llevar un cable desde la caja de derivación de un punto existente hasta una nueva ubicación dentro del mismo recinto, usando el espacio entre falso techo y forjado."],"why_section":{"title":"Cuándo conviene falso techo vs roza.","body":"El falso techo gana en estos casos:","bullets":["<strong>Pasillos y zonas comunes:</strong> casi siempre tienen falso techo registrable.","<strong>Trayectos largos (>5m):</strong> roza por pared sería interminable.","<strong>Cuando no quieres polvo de obra:</strong> el falso techo es trabajo limpio.","<strong>Conexiones múltiples:</strong> añadir varios puntos a la vez sale mucho más rentable."]},"safety_steps":[{"title":"Corta el circuito al que vas a conectar la nueva manguera","body":"Magnetotérmico de iluminación que cubrirá el nuevo punto. Si no estás seguro, corta el diferencial general."},{"title":"Verifica con polímetro en la caja de derivación origen","body":"Mide entre cualquier par de cables: 0V. Sin tensión = vía libre."},{"title":"Escalera firme con plataforma, no de tijera abierta","body":"Trabajar en falso techo es trabajo mirando hacia arriba con manos en alto. Necesitas estabilidad."},{"title":"Guantes finos, gafas y mascarilla","body":"Los falsos techos antiguos pueden tener fibra mineral o yeso degradado que se desprende — protégete."},{"title":"Linterna frontal","body":"Imprescindible. Sin las dos manos libres y luz dirigida, no se puede trabajar bien."}],"when_not":["El falso techo es de <strong>placas pegadas/atornilladas sin acceso</strong> — requiere cortarlo, no es propio del bricolaje.","Hay <strong>conductos de climatización</strong> ocupando el espacio del falso techo — puedes dañarlos con el pasacables.","El falso techo cubre <strong>vigas o instalaciones que no conoces</strong> — desmonta solo una pieza primero para confirmar.","Sospechas presencia de <strong>amianto</strong> (placas de fibrocemento muy antiguas) — para todo, llama a profesional especializado.","El recorrido cruza <strong>habitaciones diferentes con paredes cargantes</strong> que no puedes atravesar."],"steps":[{"title":"Levanta una placa del falso techo y mira","body":"Antes de plantear el trayecto, abre una placa cerca del origen y mira: ¿hay espacio? ¿hay vigas? ¿hay otras instalaciones (climatización, agua)? Toma fotos."},{"title":"Planifica el trayecto en plano","body":"Dibuja en papel cómo irá la manguera desde la caja origen hasta la nueva ubicación. Marca puntos donde abras placa para guiar el cable. Por cada metro de manguera, calcula 10% de margen extra."},{"title":"Mide y compra la manguera + tubo corrugado","body":"Manguera 3x1,5 H07V-K en color y longitud necesaria. Y un tubo PVC corrugado tipo M16 o M20 para PROTEGER la manguera (es obligatorio por reglamento RBT)."},{"title":"Mete la manguera dentro del tubo corrugado","body":"En suelo, antes de subir, mete la manguera dentro del tubo corrugado. Es difícil hacerlo en techo. Para tubos largos (>5m), usa guía pasacables para empujarla.","tip":"Lubrica con un poco de jabón líquido si la manguera no entra fluidamente."},{"title":"Tira el tubo (con manguera dentro) por el falso techo","body":"Empieza por la caja origen. Lleva el tubo hasta el primer punto donde has abierto placa. Usa una guía o pasacables para impulsarlo. Sube hasta la siguiente apertura. Repite hasta el destino.","warn":"NO tenses el tubo: debe quedar holgado entre apoyos. NO cruces tubos eléctricos sobre tuberías de agua sin separación."},{"title":"Fija el tubo con bridas a la estructura","body":"Cada 50-80 cm con brida (sin apretar mucho, debe permitir movimiento). Las bridas se anclan a viguetas, perfiles del falso techo o estructura, NUNCA al techo de pladur (no aguanta)."},{"title":"Conecta extremo origen a la caja de derivación","body":"Pela manguera 12 cm, mete por el tubo PG hacia la caja. Conecta los tres hilos a las clemas existentes: fase con fase (marrón), neutro con neutro (azul), tierra con tierra (verde-amarillo). Aprieta firme."},{"title":"Deja el extremo destino con cable pelado preparado","body":"Donde irá el nuevo punto, pela manguera 12 cm. Si todavía no tienes el mecanismo o luminaria, aísla cada hilo con clema individual o cinta. Sube corriente y verifica con polímetro que llegan 230V (entre fase y neutro)."},{"title":"Cierra las placas del falso techo","body":"Vuelve a colocar las placas que abriste. Verifica que ninguna queda mal asentada."}],"verification_checks":["La manguera llega del origen al destino sin partes vistas (todo dentro de tubo corrugado).","Al medir con polímetro en el destino: 230V entre fase y neutro.","Al medir entre fase y tierra: 230V (lo que confirma que la tierra está conectada).","Las placas del falso techo vuelven a su sitio sin holgura.","El diferencial NO salta al dar corriente — eso confirma que no has dañado el aislante de la manguera al pasarla."],"problems":[{"summary":"Salta el diferencial al dar corriente","body":"Posible derivación a tierra: un hilo pelado tocando el tubo metálico o la estructura. Saca tensión, examina el recorrido tirando suavemente — si en algún punto notas resistencia o has visto pellizcos en el tubo, ahí está el daño. Hay que recuperar la manguera y revisarla, o tirar una nueva."},{"summary":"Llega 230V entre fase y neutro pero 0V entre fase y tierra","body":"La tierra de la nueva manguera no está conectada en la caja origen. Vuelve a esa caja y revisa: el cable verde-amarillo de tu nueva manguera debe ir a la clema de tierra de la caja (NO a la de fase o neutro). Si no había clema de tierra previa, hay que hacerla."},{"summary":"El tubo se ha encajado en una zona y no avanza","body":"Probablemente has chocado con una viga o estructura. Saca el tubo unos centímetros, observa por dónde estaba bloqueando con linterna, y replantea el recorrido bordeando ese obstáculo. Si no es posible, hay que abrir otra placa en otro punto para sortear."}]}', '2026-05-10', 0);
